function sanitizeDirectorioEntry(raw) {
    if (!raw || typeof raw !== 'object') {
        return { asunto: 'Sin asunto', responsable: '', estado: '', documentos: [] };
    }
    const documentos = Array.isArray(raw.documentos)
        ? raw.documentos
            .filter(item => (typeof item === 'string' && item.trim().length) || (typeof item === 'object' && item !== null && item.url))
            .map(item => {
                if (typeof item === 'string') return item.trim();
                return { url: item.url.trim(), name: (item.name || '').trim() };
            })
        : [];
    return {
        asunto: (raw.asunto || 'Sin asunto').toString().trim() || 'Sin asunto',
        responsable: (raw.responsable || '').toString().trim(),
        estado: (raw.estado || '').toString().trim(),
        documentos
    };
}

function getDirectorioDocBasePath() {
    try {
        const listEl = document.getElementById('medicas-directorio-list');
        if (!listEl) return SERVICIO_MEDICO_DIRECTORIO_DEFAULT_BASE;
        const base = (listEl.dataset.docBase || '').trim();
        const sanitized = base.replace(/\\/g, '/').replace(/\s+/g, '');
        return sanitized || SERVICIO_MEDICO_DIRECTORIO_DEFAULT_BASE;
    } catch (err) {
        console.warn('getDirectorioDocBasePath failed:', err);
        return SERVICIO_MEDICO_DIRECTORIO_DEFAULT_BASE;
    }
}

function buildDirectorioDocUrl(filename) {
    if (!filename || typeof filename !== 'string') return null;
    const trimmed = filename.trim();
    if (!trimmed) return null;
    if (/^(https?:|data:)/i.test(trimmed)) return trimmed;
    if (trimmed.startsWith('/') || trimmed.startsWith('./') || trimmed.startsWith('../')) {
        return trimmed.replace(/\\/g, '/');
    }
    const normalized = trimmed.replace(/\\/g, '/');
    const encodedSegments = normalized
        .split('/')
        .filter(Boolean)
        .map(segment => encodeURIComponent(segment.trim()));
    const base = getDirectorioDocBasePath().replace(/\\/g, '/').replace(/\/+$/, '');
    return `${base}/${encodedSegments.join('/')}`;
}

function setDirectorioAlert(message, tone = 'info') {
    const alertEl = document.getElementById('medicas-directorio-alert');
    if (!alertEl) return;
    if (!message) {
        alertEl.classList.add('d-none');
        alertEl.textContent = '';
        return;
    }
    alertEl.className = `alert alert-${tone}`;
    alertEl.textContent = message;
    alertEl.classList.remove('d-none');
}

function toggleDirectorioLoader(visible) {
    const loader = document.getElementById('medicas-directorio-loader');
    if (!loader) return;
    loader.classList.toggle('d-none', !visible);
    loader.setAttribute('aria-hidden', visible ? 'false' : 'true');
}

function renderServicioMedicoDirectorio(entries) {
    const listEl = document.getElementById('medicas-directorio-list');
    const emptyEl = document.getElementById('medicas-directorio-empty');
    if (!listEl) return;
    toggleDirectorioLoader(false);
    if (!Array.isArray(entries) || !entries.length) {
        listEl.innerHTML = '';
        if (emptyEl) emptyEl.classList.remove('d-none');
        return;
    }
    if (emptyEl) emptyEl.classList.add('d-none');
    const escapeHtml = escapeHTML;
    const markup = entries.map((entry) => {
        const docs = entry.documentos.length
            ? entry.documentos.map((doc, docIndex) => {
                // Support both legacy string URLs and new object {url, name} format
                const isObject = typeof doc === 'object' && doc !== null;
                const rawUrl = isObject ? doc.url : doc;
                const rawName = isObject ? (doc.name || 'Documento') : doc;

                const safeLabel = escapeHtml(rawName);
                // If it's a full URL (Supabase), use it directly. If it's a relative path, build it.
                // buildDirectorioDocUrl handles relative paths well, but we need to check if it's absolute first

                let docUrl;
                if (/^(https?:|data:)/i.test(rawUrl)) {
                    docUrl = rawUrl;
                } else {
                    docUrl = buildDirectorioDocUrl(rawUrl);
                }

                const docNumber = docIndex + 1;
                if (docUrl) {
                    return `
                        <a class="btn btn-outline-primary btn-sm directorio-doc-link" href="${escapeHtml(docUrl)}" target="_blank" rel="noopener noreferrer" data-directorio-doc="${escapeHtml(rawUrl)}">
                            <i class="fas fa-file-pdf me-1" aria-hidden="true"></i>${safeLabel}
                            <span class="visually-hidden">(Documento ${docNumber})</span>
                        </a>`;
                }
                return `
                    <button type="button" class="btn btn-outline-secondary btn-sm directorio-doc-fallback" data-directorio-doc="${escapeHtml(rawUrl)}">
                        <i class="fas fa-file-circle-xmark me-1" aria-hidden="true"></i>${safeLabel}
                    </button>`;
            }).join('')
            : '<span class="badge bg-light text-muted">Sin documentos adjuntos</span>';
        const responsableLine = entry.responsable
            ? `<p class="mb-1 small text-muted"><i class="fas fa-user-tie me-1" aria-hidden="true"></i>${escapeHtml(entry.responsable)}</p>`
            : '';
        const estadoBadge = entry.estado
            ? `<span class="badge bg-primary-subtle text-primary">${escapeHtml(entry.estado)}</span>`
            : '';
        return `
            <div class="col-12">
                <div class="border rounded-3 p-3 h-100 directorio-entry">
                    <div class="d-flex flex-column flex-sm-row justify-content-between gap-2 mb-2">
                        <div>
                            <p class="text-uppercase small text-muted mb-1">Asunto</p>
                            <h4 class="h6 mb-0">${escapeHtml(entry.asunto)}${estadoBadge ? ' ' + estadoBadge : ''}</h4>
                        </div>
                    </div>
                    ${responsableLine}
                    <div class="mt-3">
                        <p class="mb-2 fw-semibold small text-muted"><i class="fas fa-folder-open me-1" aria-hidden="true"></i>Documentos</p>
                        <div class="d-flex flex-wrap gap-2">${docs}</div>
                    </div>
                </div>
            </div>`;
    }).join('');
    listEl.innerHTML = markup;
}

async function loadServicioMedicoDirectorio(options = {}) {
    const listEl = document.getElementById('medicas-directorio-list');
    if (!listEl) return;
    const { force = false } = options;
    setDirectorioAlert('', 'info');
    if (!force && Array.isArray(servicioMedicoDirectorioState.cache) && servicioMedicoDirectorioState.cache.length) {
        renderServicioMedicoDirectorio(servicioMedicoDirectorioState.cache);
        return;
    }
    toggleDirectorioLoader(true);

    // Try fetching from DB first via dataManager
    try {
        if (window.dataManager) {
            console.log('Fetching Medical Directory from DB...');
            const dbData = await window.dataManager.getMedicalDirectory();

            if (dbData && dbData.length > 0) {
                // Map DB columns to UI format
                const entries = dbData.map(row => ({
                    asunto: row.asunto || 'Sin asunto',
                    responsable: row.responsable || '',
                    estado: row.estado || '',
                    documentos: Array.isArray(row.documentos) ? row.documentos : (typeof row.documentos === 'string' ? JSON.parse(row.documentos) : [])
                }));

                servicioMedicoDirectorioState.cache = entries;
                servicioMedicoDirectorioState.lastFetch = Date.now();
                renderServicioMedicoDirectorio(entries);
                return; // Success, exit
            }
        }
    } catch (dbError) {
        console.warn('DB fetch for Medical Directory failed, falling back to JSON:', dbError);
    }


    try {
        if (servicioMedicoDirectorioState.inFlight && !force) {
            await servicioMedicoDirectorioState.inFlight;
            renderServicioMedicoDirectorio(servicioMedicoDirectorioState.cache || []);
            return;
        }
        const fetchPromise = fetch(SERVICIO_MEDICO_DIRECTORIO_DATA_PATH, { cache: 'no-store' })
            .then((res) => {
                if (!res.ok) {
                    throw new Error(`HTTP ${res.status}`);
                }
                return res.json();
            })
            .then((payload) => {
                const entries = Array.isArray(payload) ? payload.map(sanitizeDirectorioEntry) : [];
                servicioMedicoDirectorioState.cache = entries;
                servicioMedicoDirectorioState.lastFetch = Date.now();
                return entries;
            });
        servicioMedicoDirectorioState.inFlight = fetchPromise;
        const entries = await fetchPromise;
        renderServicioMedicoDirectorio(entries);
    } catch (err) {
        console.warn('loadServicioMedicoDirectorio failed:', err);
        setDirectorioAlert('No se pudo cargar el directorio. Intenta nuevamente.', 'warning');
        toggleDirectorioLoader(false);
        const emptyEl = document.getElementById('medicas-directorio-empty');
        if (emptyEl) emptyEl.classList.remove('d-none');
    } finally {
        servicioMedicoDirectorioState.inFlight = null;
    }
}

function initServicioMedicoDirectorio() {
    const reloadBtn = document.getElementById('medicas-directorio-reload');
    if (reloadBtn && !reloadBtn._wired) {
        reloadBtn._wired = 1;
        reloadBtn.addEventListener('click', () => {
            loadServicioMedicoDirectorio({ force: true }).catch((err) => console.warn('reload directorio failed:', err));
        });
    }
    loadServicioMedicoDirectorio().catch((err) => console.warn('init directorio failed:', err));
}

function handleDirectorioDocClick(target) {
    if (!target) return;
    const docName = target.getAttribute('data-directorio-doc');
    const url = buildDirectorioDocUrl(docName);
    if (!url) {
        setDirectorioAlert('No se pudo abrir el documento solicitado.', 'warning');
        return;
    }
    try {
        window.open(url, '_blank', 'noopener,noreferrer');
    } catch (err) {
        console.warn('handleDirectorioDocClick failed:', err);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    initServicioMedicoDirectorio();
});

document.addEventListener('click', (event) => {
    const trigger = event.target?.closest?.('.directorio-doc-fallback, .directorio-doc-link');
    if (!trigger) return;
    const isAnchorWithHref = trigger.tagName === 'A' && trigger.getAttribute('href');
    if (isAnchorWithHref) return; // let browser handle real links
    event.preventDefault();
    handleDirectorioDocClick(trigger);
});

function normalizeSectionKey(key) {
    return (key || '').toString().trim();
}

function resetSectionPermissions() {
    userSectionWhitelist = null;
    userDefaultSectionKey = 'operaciones-totales';
    document.querySelectorAll('.menu-item[data-section]').forEach((item) => item.classList.remove('perm-hidden'));
    document.querySelectorAll('.content-section').forEach((section) => section.classList.remove('perm-hidden'));
    // Restore all sidebar group containers
    document.querySelectorAll('#sidebar-nav .si-group').forEach(group => group.classList.remove('perm-hidden'));
}

/**
 * After hiding individual menu-item links, also hide any .si-group container
 * whose every .menu-item[data-section] descendant is already perm-hidden.
 * Processes innermost groups first so parent groups react correctly.
 */
function hideEmptySidebarGroups() {
    // If any menu items are currently perm-hidden, the user is in restricted mode.
    // In restricted mode, also hide "Próximamente" groups that have no real links.
    const hasHiddenItems = document.querySelectorAll('#sidebar-nav .menu-item[data-section].perm-hidden').length > 0;
    const allGroups = Array.from(document.querySelectorAll('#sidebar-nav .si-group'));
    // Reverse so deepest (innermost) groups are processed first
    allGroups.reverse().forEach(group => {
        const menuItems = Array.from(group.querySelectorAll('.menu-item[data-section]'));
        if (menuItems.length === 0) {
            // "Próximamente" decoration group — hide it when user is in restricted mode
            if (hasHiddenItems) group.classList.add('perm-hidden');
            return;
        }
        const allHidden = menuItems.every(item => item.classList.contains('perm-hidden'));
        if (allHidden) group.classList.add('perm-hidden');
    });
}

function isSectionAllowed(sectionKey) {
    if (!sectionKey) return true;
    if (!Array.isArray(userSectionWhitelist) || !userSectionWhitelist.length) return true;
    return userSectionWhitelist.includes(sectionKey);
}

function getDefaultAllowedSection() {
    if (Array.isArray(userSectionWhitelist) && userSectionWhitelist.length) {
        if (userDefaultSectionKey && userSectionWhitelist.includes(userDefaultSectionKey)) {
            return userDefaultSectionKey;
        }
        return userSectionWhitelist[0];
    }
    return 'operaciones-totales';
}

function applySectionPermissions(userName) {
    resetSectionPermissions();

    const role = sessionStorage.getItem('user_role') || 'viewer';
    const isColabOnly = ['colab_viewer', 'colab_editor'].includes(role);
    // Conciliación es un módulo base para toda sesión válida (la base de datos
    // conserva sus propios permisos RLS). Mantener esta regla igual que
    // js/permissions.js evita que una capa la muestre y la otra la vuelva a
    // ocultar durante el arranque.
    const authenticatedCoreSections = ['conciliacion'];

    // admin y superadmin: acceso total siempre, sin importar allowed_sections
    const isFullAdmin = ['admin', 'superadmin'].includes(role);
    if (isFullAdmin) {
        return;
    }

    // ¿El admin configuró una lista EXPLÍCITA de módulos? (incluye el centinela
    // '__none__' = sin módulos). Si es así, esa lista MANDA sobre cualquier
    // bloqueo histórico por rol (p.ej. cuentas "solo colaboradores"), para que
    // el usuario entre únicamente a los módulos designados en el administrador.
    let explicitWhitelist = [];
    try {
        const raw = sessionStorage.getItem('user_allowed_sections');
        if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed) && parsed.length > 0) {
                explicitWhitelist = parsed.map(s => normalizeSectionKey(s)).filter(Boolean);
                authenticatedCoreSections.forEach(sectionKey => {
                    if (!explicitWhitelist.includes(sectionKey)) explicitWhitelist.push(sectionKey);
                });
            }
        }
    } catch (_) {}
    const hasExplicitWhitelist = explicitWhitelist.length > 0;

    // Roles de solo-Colaboradores: conservar Colaboradores y los módulos base
    // autenticados. Si el admin designó módulos concretos, se respeta esa lista
    // ampliada con el mismo núcleo autenticado.
    if (isColabOnly && !hasExplicitWhitelist) {
        document.querySelectorAll('.menu-item[data-section]').forEach(item => {
            if (item.dataset.section !== 'colaboradores' && !authenticatedCoreSections.includes(item.dataset.section)) {
                item.classList.add('perm-hidden');
            }
        });
        document.querySelectorAll('.content-section').forEach(sectionEl => {
            const key = (sectionEl.id || '').replace(/-section$/, '');
            if (key !== 'colaboradores' && !authenticatedCoreSections.includes(key)) {
                sectionEl.classList.add('perm-hidden');
                sectionEl.classList.remove('active');
            }
        });
        hideEmptySidebarGroups();
        // No navegar automáticamente: showMainApp restaurará el hash solicitado
        // (#conciliacion incluido) y sólo usará el menú cuando no exista ruta.
        return;
    }

    // Force hide sensitive sections for non-power users (Viewers)
    // data-management puede desbloquearse si el admin lo añade al allowed_sections del usuario
    const sensitive = ['admin-usuarios'];
    // data-management: ocultar solo si no está en el whitelist
    const supabaseWhitelistForSensitive = (() => { try { const r = sessionStorage.getItem('user_allowed_sections'); return r ? JSON.parse(r) : []; } catch(_) { return []; } })();
    if (!supabaseWhitelistForSensitive.includes('data-management')) sensitive.push('data-management');

    sensitive.forEach(secKey => {
        const item = document.querySelector(`.menu-item[data-section="${secKey}"]`);
        if (item) item.classList.add('perm-hidden');

        const content = document.getElementById(`${secKey}-section`);
        if (content) content.classList.add('perm-hidden');
    });

    const users = dashboardData?.users || {};
    const user = users[userName];
    const legacyList = Array.isArray(user?.allowedSections)
        ? user.allowedSections.map((section) => normalizeSectionKey(section)).filter(Boolean)
        : [];

    // Para usuarios Supabase: allowed_sections ya se leyó arriba (explicitWhitelist).
    const supabaseList = explicitWhitelist.slice();

    // Preferir Supabase; caer en legacy si no hay Supabase
    const rawWhitelist = supabaseList.length ? supabaseList : legacyList;
    if (rawWhitelist.length) {
        authenticatedCoreSections.forEach(sectionKey => {
            if (!rawWhitelist.includes(sectionKey)) rawWhitelist.push(sectionKey);
        });
    }

    // Permitir siempre la sección de historia y biblioteca SOLO en whitelist legacy (no Supabase)
    if (rawWhitelist.length && !supabaseList.length) {
        if (!rawWhitelist.includes('historia')) rawWhitelist.push('historia');
        if (!rawWhitelist.includes('biblioteca')) rawWhitelist.push('biblioteca');
        // colaboradores: solo si el usuario lo tiene explícitamente en su legacy whitelist
    }

    if (rawWhitelist.length) {
        userSectionWhitelist = [...new Set(rawWhitelist)];
        const preferred = normalizeSectionKey(user?.defaultSection);
        userDefaultSectionKey = preferred && userSectionWhitelist.includes(preferred)
            ? preferred
            : userSectionWhitelist[0];

        document.querySelectorAll('.menu-item[data-section]').forEach((item) => {
            const sectionKey = normalizeSectionKey(item.dataset.section);
            if (!userSectionWhitelist.includes(sectionKey)) {
                item.classList.add('perm-hidden');
            }
        });
        document.querySelectorAll('.content-section').forEach((sectionEl) => {
            const key = normalizeSectionKey((sectionEl.id || '').replace(/-section$/, ''));
            if (!userSectionWhitelist.includes(key)) {
                sectionEl.classList.add('perm-hidden');
                sectionEl.classList.remove('active');
            }
        });

        hideEmptySidebarGroups();

        if (!isSectionAllowed(currentSectionKey)) {
            const fallback = getDefaultAllowedSection();
            const fallbackLink = document.querySelector(`.menu-item[data-section="${fallback}"]`);
            showSection(fallback, fallbackLink);
        }
    }

    // Colaboradores: oculto para viewers a menos que se haya otorgado acceso explícito
    const colabGranted = (() => {
        try {
            const secs = JSON.parse(sessionStorage.getItem('user_allowed_sections') || 'null');
            if (Array.isArray(secs) && secs.includes('colaboradores')) return true;
        } catch (_) {}
        const legacyUser = (dashboardData?.users || {})[userName];
        return Array.isArray(legacyUser?.allowedSections) &&
            legacyUser.allowedSections.some(s => normalizeSectionKey(s) === 'colaboradores');
    })();
    if (!colabGranted) {
        const colabMenuItem = document.querySelector('.menu-item[data-section="colaboradores"]');
        if (colabMenuItem) colabMenuItem.classList.add('perm-hidden');
        const colabSection = document.getElementById('colaboradores-section');
        if (colabSection) { colabSection.classList.add('perm-hidden'); colabSection.classList.remove('active'); }
    }
    // Re-run after colaboradores adjustment to catch any newly-emptied groups
    hideEmptySidebarGroups();

    // Itinerario Mensual: unify hiding under the perm-hidden system so it re-runs
    // correctly every time applySectionPermissions is called (including async re-fetches).
    const itinerarioItem = document.querySelector('.menu-item[data-section="itinerario-mensual"]');
    const itinerarioSection = document.getElementById('itinerario-mensual-section');
    if (itinerarioItem || itinerarioSection) {
        const inWhitelist = Array.isArray(userSectionWhitelist) && userSectionWhitelist.includes('itinerario-mensual');
        // If a whitelist is active, rely solely on the whitelist (already applied above).
        // If no whitelist: fall back to the legacy canViewItinerarioMensual flag.
        const legacyUser = (dashboardData?.users || {})[userName];
        const legacyCanView = !!(legacyUser && legacyUser.canViewItinerarioMensual);
        const hasWhitelist = Array.isArray(userSectionWhitelist) && userSectionWhitelist.length > 0;
        const canView = hasWhitelist ? inWhitelist : legacyCanView;
        if (!canView) {
            if (itinerarioItem) itinerarioItem.classList.add('perm-hidden');
            if (itinerarioSection) {
                itinerarioSection.classList.add('perm-hidden');
                itinerarioSection.classList.remove('active');
            }
        }
    }

    // Salvaguarda final: si la sección actualmente ACTIVA quedó oculta por
    // permisos (p.ej. tras cerrar sesión con #colaboradores en la URL y volver
    // a entrar sin permiso para esa sección), redirigir a una permitida. Cubre
    // tanto usuarios con whitelist como sin ella (allowed_sections vacío = todo,
    // pero colaboradores/data-management/admin-usuarios siguen ocultos).
    try {
        // Helper: ¿esta clave de sección está oculta/ prohibida para el usuario?
        const _isSectionHidden = (key) => {
            if (!key) return false;
            const item = document.querySelector(`.menu-item[data-section="${key}"]`);
            const sec  = document.getElementById(`${key}-section`);
            return (item && item.classList.contains('perm-hidden')) ||
                   (sec && sec.classList.contains('perm-hidden')) ||
                   !isSectionAllowed(key);
        };

        let activeSection = document.querySelector('.content-section.active');
        // Si la sección activa quedó oculta —o no hay ninguna activa (el bloque
        // colabGranted pudo quitar 'active' sin poner otra)— navegar a una permitida.
        if (!activeSection || activeSection.classList.contains('perm-hidden')) {
            const fallback = getDefaultAllowedSection() || 'operaciones-totales';
            const fallbackLink = document.querySelector(`.menu-item[data-section="${fallback}"]`);
            if (typeof showSection === 'function') showSection(fallback, fallbackLink);
            activeSection = document.querySelector('.content-section.active');
        }

        // Normalizar el hash de la URL: si apunta a una sección oculta por
        // permisos (p.ej. #colaboradores heredado de una sesión previa), o no
        // coincide con la sección realmente activa, reemplazarlo. Esto evita el
        // desajuste "contenido = Operaciones, pero la barra dice #colaboradores".
        const hashKey = (location.hash || '').replace(/^#/, '');
        const activeKey = activeSection
            ? (activeSection.id || '').replace(/-section$/, '')
            : (getDefaultAllowedSection() || 'operaciones-totales');
        if (hashKey && (_isSectionHidden(hashKey) || hashKey !== activeKey)) {
            history.replaceState(null, '', `#${activeKey}`);
        }
    } catch (_) {}
}

// Guardia de hash: revierte cualquier cambio de URL (barra de direcciones,
// back/forward, ancla no interceptada) que apunte a una sección oculta por
// permisos. showSection usa history.replaceState (no dispara 'hashchange'),
// por lo que esta guardia NO interfiere con la navegación normal del menú.
let _hashGuardInstalled = false;
function installSectionHashGuard() {
    if (_hashGuardInstalled) return;
    _hashGuardInstalled = true;
    window.addEventListener('hashchange', () => {
        try {
            // Solo con sesión activa
            if (!sessionStorage.getItem(SESSION_USER)) return;
            const key = (location.hash || '').replace(/^#/, '');
            if (!key || key === 'recover') return;
            const item = document.querySelector(`.menu-item[data-section="${key}"]`);
            const sec  = document.getElementById(`${key}-section`);
            const hidden = (item && item.classList.contains('perm-hidden')) ||
                           (sec && sec.classList.contains('perm-hidden')) ||
                           !isSectionAllowed(key);
            if (hidden) {
                const active = document.querySelector('.content-section.active');
                const activeKey = active
                    ? (active.id || '').replace(/-section$/, '')
                    : (getDefaultAllowedSection() || 'operaciones-totales');
                history.replaceState(null, '', `#${activeKey}`);
            }
        } catch (_) {}
    });
}

// Re-lee rol/área/allowed_sections del usuario actual desde Supabase y re-aplica
// los permisos si cambiaron. Se usa al iniciar y de forma periódica (propagación
// en vivo), para que los cambios que hace el admin se reflejen sin recargar.
async function refreshUserPermissionsFromServer() {
    try {
        if (!window.supabaseClient) return;
        const { data: { user } } = await window.supabaseClient.auth.getUser();
        if (!user) return;
        const { data: roleData } = await window.supabaseClient
            .from('user_roles').select('role, permissions').eq('user_id', user.id).single();
        if (!roleData) return;
        // Cambio de contraseña forzado: si un admin restableció la contraseña,
        // permissions.must_change_password === true → obligar a cambiarla ahora.
        try {
            if (roleData?.permissions?.must_change_password === true
                && typeof window.pwOpenForcedChange === 'function') {
                window.pwOpenForcedChange();
            }
        } catch (_) {}
        const name = sessionStorage.getItem('user_fullname') || sessionStorage.getItem(SESSION_USER) || '';
        // Actualizar rol si cambió
        if (roleData.role) sessionStorage.setItem('user_role', roleData.role);
        // Actualizar área: override > role legacy > role=clave directa
        const _GL = ['admin','superadmin','editor','viewer','colab_viewer','colab_editor'];
        const _LG = { operacion:'DO', administracion:'DA', planeacion:'DPE', comercial:'DCS', seguridad_op:'GSO', transparencia:'UT', calidad:'GC' };
        const _rr = roleData?.role;
        const _area = roleData?.permissions?.area || _LG[_rr] || (!_GL.includes(_rr) && _rr ? _rr : null);
        if (_area) sessionStorage.setItem('user_area', _area);
        else sessionStorage.removeItem('user_area');
        // Refrescar badge de área/rol en el header si cambió
        const userEl = document.getElementById('current-user');
        if (userEl) {
            const _freshArea = _area || null;
            const _freshRole = roleData.role || sessionStorage.getItem('user_role') || 'viewer';
            const _RDISPLAY  = { admin:'Admin', superadmin:'Superadmin', editor:'Editor', viewer:'Viewer', colab_viewer:'Colaborador', colab_editor:'Colaborador Ed.' };
            const _rdLabel   = _RDISPLAY[_freshRole] || (_freshRole.charAt(0).toUpperCase() + _freshRole.slice(1));
            let _aHtml = '';
            if (_freshArea) {
                const _ac  = (typeof AG_AREA !== 'undefined' && AG_AREA[_freshArea]) || null;
                const _bg  = _ac ? _ac.border : '#6366f1';
                const _txt = _ac ? _ac.name   : _freshArea;
                _aHtml = `<div style="margin-top:3px"><span style="display:inline-flex;align-items:center;gap:4px;background:${_bg}22;color:${_bg};border:1px solid ${_bg}55;border-radius:20px;padding:1px 8px;font-size:.68em;font-weight:600;letter-spacing:.3px"><span style="width:6px;height:6px;border-radius:50%;background:${_bg};display:inline-block"></span>${_txt}</span></div>`;
            }
            const _fn = sessionStorage.getItem('user_fullname') || name;
            userEl.innerHTML = `<div>${_fn}</div><div style="font-size:.8em;font-weight:400;opacity:.9">${_rdLabel}</div>${_aHtml}`;
        }
        // Actualizar allowed_sections. Ojo: [] (acceso total) y ['__none__']
        // (sin módulos) son estados válidos que deben propagarse, por eso se
        // compara la representación completa, no solo "length > 0".
        const secs = roleData?.permissions?.allowed_sections;
        const prev = sessionStorage.getItem('user_allowed_sections');
        const next = Array.isArray(secs) ? JSON.stringify(secs) : null;
        // Comparar el JSON en crudo hacía que un simple REORDENAMIENTO de la
        // lista que devuelve el servidor contara como "cambiaron los permisos".
        // La consulta no lleva ORDER BY, así que el mismo conjunto puede volver
        // en otro orden entre dos sondeos; eso disparaba applySectionPermissions,
        // que tiene dos caminos que navegan a la sección por defecto, y el
        // usuario aparecía de pronto en otro módulo sin haber tocado nada.
        const permisosCambiaron = _seccionesPermitidasCambiaron(prev, next);
        if (next !== prev) {
            if (next) sessionStorage.setItem('user_allowed_sections', next);
            else sessionStorage.removeItem('user_allowed_sections');
        }
        if (permisosCambiaron) {
            applySectionPermissions(sessionStorage.getItem(SESSION_USER) || name);
        }
        // El lanzador modal vive fuera de #sidebar-nav y mantiene su propia
        // visibilidad. Sincronizarlo también cuando los permisos cambian en vivo.
        try {
            window.miscelaneaModule?.syncVisibility({
                role: roleData.role,
                permissions: roleData.permissions || {}
            });
        } catch (_) {}
        // ESTE era el disparador de la navegación involuntaria.
        //
        // Antes se re-navegaba a la sección del hash en CADA vuelta del sondeo
        // (cada 60 s), hubiera cambiado algo o no. Y se hacía por showSection
        // pasándole el elemento del menú, es decir, por el mismo camino que un
        // clic deliberado del usuario: showSection honra el data-sub-tab de ese
        // elemento y reimpone la sub-pestaña por defecto de la sección. Quien
        // estuviera trabajando en otra sub-pestaña era devuelto a la de arranque
        // cada minuto, sin haber tocado nada.
        //
        // Ahora sólo se re-navega cuando los permisos REALMENTE cambiaron —que
        // es lo único que justificaba re-aplicar la ruta— y se pide conservar la
        // pestaña activa, porque esto nunca es un clic del usuario.
        if (permisosCambiaron) {
            const routeKey = String(location.hash || '').replace(/^#/, '').trim();
            if (routeKey) restoreSectionFromNavigation(routeKey, { preserveActiveTab: true });
        }
    } catch (_) {}
}

// ¿Cambió de verdad el conjunto de secciones permitidas? Compara CONJUNTOS, no
// el texto: el mismo listado en distinto orden no es un cambio de permisos.
// null (sin restricción) y [] son estados distintos y deben distinguirse.
function _seccionesPermitidasCambiaron(prevJson, nextJson) {
    if (prevJson === nextJson) return false;
    const aLista = (json) => {
        if (json === null || json === undefined) return null;
        try {
            const v = JSON.parse(json);
            return Array.isArray(v) ? [...new Set(v.map(String))].sort() : null;
        } catch (_) { return null; }
    };
    const a = aLista(prevJson);
    const b = aLista(nextJson);
    if (a === null || b === null) return a !== b;
    return a.length !== b.length || a.some((v, i) => v !== b[i]);
}

// Polling ligero para propagar en vivo los cambios de permisos (cada 60 s).
let _permsAutoRefreshTimer = null;
function startPermissionsAutoRefresh() {
    if (_permsAutoRefreshTimer) return; // ya iniciado
    _permsAutoRefreshTimer = setInterval(() => {
        // Solo si hay sesión activa y la app está visible
        if (!sessionStorage.getItem(SESSION_USER)) return;
        if (document.hidden) return;
        refreshUserPermissionsFromServer();
    }, 60000);
}
// ============================================================================
// Gestión de contraseñas: cambio propio + restablecimiento (admin) + cambio
// forzado tras restablecimiento (must_change_password).
//   • pwOpenChangeOwn()       → modal de cambio de contraseña propia.
//   • auResetPassword(id,mail) → modal admin para fijar contraseña temporal.
//   • pwOpenForcedChange()     → modal obligatorio (no se puede cerrar).
// Depende de las RPC de db/admin_password_management.sql y de
// supabaseClient.auth.updateUser({ password }).
// ============================================================================
(function _pwPasswordModule() {
    let _forcedOpen = false;

    function genTempPassword() {
        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
        let out = '';
        const arr = new Uint32Array(10);
        if (window.crypto && window.crypto.getRandomValues) {
            window.crypto.getRandomValues(arr);
        } else {
            for (let i = 0; i < arr.length; i++) arr[i] = Math.floor(Math.random() * 1e9);
        }
        for (let i = 0; i < 10; i++) out += chars[arr[i] % chars.length];
        return 'Aifa-' + out;
    }

    function ensureUI() {
        if (document.getElementById('pw-change-modal')) return;
        const wrap = document.createElement('div');
        wrap.innerHTML = `
        <div class="modal fade" id="pw-change-modal" tabindex="-1" aria-hidden="true">
          <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
              <div class="modal-header">
                <h5 class="modal-title"><i class="fas fa-key me-2 text-primary"></i>Cambiar contraseña</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Cerrar"></button>
              </div>
              <div class="modal-body">
                <div class="mb-3">
                  <label class="form-label small fw-semibold">Contraseña actual</label>
                  <input type="password" class="form-control" id="pw-current" autocomplete="current-password">
                </div>
                <div class="mb-3">
                  <label class="form-label small fw-semibold">Nueva contraseña</label>
                  <input type="password" class="form-control" id="pw-new" autocomplete="new-password">
                  <div class="form-text">Mínimo 6 caracteres.</div>
                </div>
                <div class="mb-2">
                  <label class="form-label small fw-semibold">Confirmar nueva contraseña</label>
                  <input type="password" class="form-control" id="pw-new2" autocomplete="new-password">
                </div>
                <div id="pw-change-msg" class="small mt-2"></div>
              </div>
              <div class="modal-footer">
                <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button>
                <button type="button" class="btn btn-primary" id="pw-change-save"><i class="fas fa-save me-1"></i>Guardar</button>
              </div>
            </div>
          </div>
        </div>

        <div class="modal fade" id="pw-forced-modal" tabindex="-1" aria-hidden="true" data-bs-backdrop="static" data-bs-keyboard="false">
          <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
              <div class="modal-header" style="background:#fff3cd">
                <h5 class="modal-title"><i class="fas fa-shield-alt me-2 text-warning"></i>Debes cambiar tu contraseña</h5>
              </div>
              <div class="modal-body">
                <p class="small text-muted">Tu contraseña fue restablecida por un administrador. Define una nueva para continuar.</p>
                <div class="mb-3">
                  <label class="form-label small fw-semibold">Nueva contraseña</label>
                  <input type="password" class="form-control" id="pwf-new" autocomplete="new-password">
                  <div class="form-text">Mínimo 6 caracteres.</div>
                </div>
                <div class="mb-2">
                  <label class="form-label small fw-semibold">Confirmar nueva contraseña</label>
                  <input type="password" class="form-control" id="pwf-new2" autocomplete="new-password">
                </div>
                <div id="pw-forced-msg" class="small mt-2"></div>
              </div>
              <div class="modal-footer">
                <button type="button" class="btn btn-outline-danger" id="pwf-logout"><i class="fas fa-sign-out-alt me-1"></i>Cerrar sesión</button>
                <button type="button" class="btn btn-warning fw-semibold" id="pwf-save"><i class="fas fa-save me-1"></i>Guardar y continuar</button>
              </div>
            </div>
          </div>
        </div>

        <div class="modal fade" id="pw-reset-modal" tabindex="-1" aria-hidden="true">
          <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
              <div class="modal-header">
                <h5 class="modal-title"><i class="fas fa-key me-2 text-secondary"></i>Restablecer contraseña</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Cerrar"></button>
              </div>
              <div class="modal-body">
                <p class="small text-muted mb-2">Usuario: <strong id="pw-reset-email"></strong></p>
                <label class="form-label small fw-semibold">Contraseña temporal</label>
                <div class="input-group">
                  <input type="text" class="form-control" id="pw-reset-temp">
                  <button class="btn btn-outline-secondary" type="button" id="pw-reset-gen" title="Generar otra"><i class="fas fa-dice"></i></button>
                  <button class="btn btn-outline-secondary" type="button" id="pw-reset-copy" title="Copiar"><i class="fas fa-copy"></i></button>
                </div>
                <div class="form-text">El usuario deberá cambiarla al iniciar sesión. Mínimo 6 caracteres.</div>
                <div id="pw-reset-msg" class="small mt-2"></div>
              </div>
              <div class="modal-footer">
                <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button>
                <button type="button" class="btn btn-primary" id="pw-reset-save"><i class="fas fa-check me-1"></i>Restablecer</button>
              </div>
            </div>
          </div>
        </div>`;
        document.body.appendChild(wrap);
        wireEvents();
    }

    function bsModal(id) {
        const el = document.getElementById(id);
        if (!el || !window.bootstrap) return null;
        return window.bootstrap.Modal.getOrCreateInstance(el);
    }

    function msg(id, html, cls) {
        const el = document.getElementById(id);
        if (el) el.innerHTML = html ? `<span class="text-${cls || 'muted'}">${html}</span>` : '';
    }

    function wireEvents() {
        // ── Cambio propio ──────────────────────────────────────────────
        document.getElementById('pw-change-save').addEventListener('click', async () => {
            const cur = document.getElementById('pw-current').value || '';
            const nw  = document.getElementById('pw-new').value || '';
            const nw2 = document.getElementById('pw-new2').value || '';
            if (nw.length < 6)  { msg('pw-change-msg', '<i class="fas fa-exclamation-circle me-1"></i>La nueva contraseña debe tener al menos 6 caracteres.', 'danger'); return; }
            if (nw !== nw2)     { msg('pw-change-msg', '<i class="fas fa-exclamation-circle me-1"></i>Las contraseñas no coinciden.', 'danger'); return; }
            const email = sessionStorage.getItem(SESSION_USER) || '';
            const btn = document.getElementById('pw-change-save');
            btn.disabled = true;
            msg('pw-change-msg', '<i class="fas fa-spinner fa-spin me-1"></i>Verificando…', 'muted');
            try {
                // Verificar contraseña actual re-autenticando al mismo usuario.
                const { error: authErr } = await window.supabaseClient.auth.signInWithPassword({ email, password: cur });
                if (authErr) throw new Error('La contraseña actual es incorrecta.');
                const { error } = await window.supabaseClient.auth.updateUser({ password: nw });
                if (error) throw error;
                msg('pw-change-msg', '<i class="fas fa-check-circle me-1"></i>Contraseña actualizada correctamente.', 'success');
                setTimeout(() => { const m = bsModal('pw-change-modal'); if (m) m.hide(); }, 1200);
            } catch (e) {
                msg('pw-change-msg', '<i class="fas fa-times-circle me-1"></i>' + (e.message || 'No se pudo cambiar la contraseña.'), 'danger');
            } finally {
                btn.disabled = false;
            }
        });

        // ── Cambio forzado (tras restablecimiento admin) ───────────────
        document.getElementById('pwf-save').addEventListener('click', async () => {
            const nw  = document.getElementById('pwf-new').value || '';
            const nw2 = document.getElementById('pwf-new2').value || '';
            if (nw.length < 6) { msg('pw-forced-msg', '<i class="fas fa-exclamation-circle me-1"></i>Mínimo 6 caracteres.', 'danger'); return; }
            if (nw !== nw2)    { msg('pw-forced-msg', '<i class="fas fa-exclamation-circle me-1"></i>Las contraseñas no coinciden.', 'danger'); return; }
            const btn = document.getElementById('pwf-save');
            btn.disabled = true;
            msg('pw-forced-msg', '<i class="fas fa-spinner fa-spin me-1"></i>Guardando…', 'muted');
            try {
                const { error } = await window.supabaseClient.auth.updateUser({ password: nw });
                if (error) throw error;
                // Limpiar la bandera must_change_password del propio usuario.
                try { await window.supabaseClient.rpc('clear_my_must_change_password'); } catch (_) {}
                msg('pw-forced-msg', '<i class="fas fa-check-circle me-1"></i>Contraseña actualizada. Continuando…', 'success');
                _forcedOpen = false;
                setTimeout(() => { const m = bsModal('pw-forced-modal'); if (m) m.hide(); }, 1000);
            } catch (e) {
                msg('pw-forced-msg', '<i class="fas fa-times-circle me-1"></i>' + (e.message || 'No se pudo cambiar la contraseña.'), 'danger');
            } finally {
                btn.disabled = false;
            }
        });
        document.getElementById('pwf-logout').addEventListener('click', () => {
            _forcedOpen = false;
            const m = bsModal('pw-forced-modal'); if (m) m.hide();
            try { if (typeof performLogout === 'function') performLogout(); } catch (_) {}
        });

        // ── Restablecer (admin) ────────────────────────────────────────
        document.getElementById('pw-reset-gen').addEventListener('click', () => {
            document.getElementById('pw-reset-temp').value = genTempPassword();
        });
        document.getElementById('pw-reset-copy').addEventListener('click', async () => {
            const v = document.getElementById('pw-reset-temp').value || '';
            try { await navigator.clipboard.writeText(v); msg('pw-reset-msg', '<i class="fas fa-check me-1"></i>Copiada al portapapeles.', 'success'); }
            catch (_) { msg('pw-reset-msg', 'Cópiala manualmente.', 'muted'); }
        });
        document.getElementById('pw-reset-save').addEventListener('click', async () => {
            const userId = document.getElementById('pw-reset-save').dataset.userId || '';
            const temp   = document.getElementById('pw-reset-temp').value || '';
            if (temp.length < 6) { msg('pw-reset-msg', '<i class="fas fa-exclamation-circle me-1"></i>Mínimo 6 caracteres.', 'danger'); return; }
            const btn = document.getElementById('pw-reset-save');
            btn.disabled = true;
            msg('pw-reset-msg', '<i class="fas fa-spinner fa-spin me-1"></i>Restableciendo…', 'muted');
            try {
                const { data, error } = await window.supabaseClient
                    .rpc('admin_reset_user_password', { p_user_id: userId, p_new_password: temp });
                if (error) throw error;
                if (data && data.ok === false) throw new Error(data.error || 'Error desconocido');
                msg('pw-reset-msg', `<i class="fas fa-check-circle me-1"></i>Contraseña temporal fijada: <code>${temp}</code>. El usuario deberá cambiarla al iniciar sesión.`, 'success');
            } catch (e) {
                msg('pw-reset-msg', '<i class="fas fa-times-circle me-1"></i>' + (e.message || 'No se pudo restablecer.'), 'danger');
            } finally {
                btn.disabled = false;
            }
        });
    }

    window.pwOpenChangeOwn = function () {
        ensureUI();
        ['pw-current', 'pw-new', 'pw-new2'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
        msg('pw-change-msg', '');
        const m = bsModal('pw-change-modal'); if (m) m.show();
    };

    window.pwOpenForcedChange = function () {
        ensureUI();
        if (_forcedOpen) return;
        _forcedOpen = true;
        ['pwf-new', 'pwf-new2'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
        msg('pw-forced-msg', '');
        const m = bsModal('pw-forced-modal'); if (m) m.show();
    };

    window.auResetPassword = function (userId, email) {
        ensureUI();
        document.getElementById('pw-reset-email').textContent = email || '—';
        document.getElementById('pw-reset-temp').value = genTempPassword();
        document.getElementById('pw-reset-save').dataset.userId = userId;
        msg('pw-reset-msg', '');
        const m = bsModal('pw-reset-modal'); if (m) m.show();
    };
})();

// Salvaguarda de arranque: la autenticación real es Supabase. Si por error se
// reintrodujera un campo `password` en dashboardData.users, aquí se elimina para
// evitar exponer credenciales en el cliente.
async function initAuthHashes() {
    try {
        const entries = Object.entries(dashboardData.users || {});
        for (const [, info] of entries) {
            if (!info || typeof info.password === 'undefined') continue;
            try { delete info.password; } catch (_) { info.password = undefined; }
        }
    } catch (_) { /* noop */ }
}
let authHashesInitPromise = null;
function ensureAuthHashes() {
    if (!authHashesInitPromise) {
        authHashesInitPromise = initAuthHashes().catch(err => {
            authHashesInitPromise = null;
            throw err;
        });
    }
    return authHashesInitPromise;
}
let passengerAirlines = ["Viva", "Volaris", "Aeromexico", "Mexicana de Aviación", "Aerus", "Arajet", "Air France", "Qatar Airways", "KLM", "British Airways"];
let cargoAirlines = ["MasAir", "China Southerrn", "Lufthansa", "Kalitta Air", "Aerounión", "Emirates Airlines", "Atlas Air", "Silk Way West Airlines", "Cathay Pacific", "United Parcel Service", "Turkish Airlines", "Cargojet Airways", "Air Canada", "Cargolux"];
const airlineColors = { "Viva": "#00b200", "Volaris": "#6f2da8", "Aeromexico": "#00008b", "Mexicana de Aviación": "#a52a2a", "Aerus": "#ff4500", "Arajet": "#00ced1", "MasAir": "#4682b4", "China Southerrn": "#c71585", "Lufthansa": "#ffcc00", "Kalitta Air": "#dc143c", "Aerounión": "#2e8b57", "Emirates Airlines": "#d4af37", "Atlas Air": "#808080", "Silk Way West Airlines": "#f4a460", "Cathay Pacific": "#006400", "United Parcel Service": "#5f4b32", "Turkish Airlines": "#e81123", "Cargojet Airways": "#f0e68c", "Air Canada": "#f00", "Cargolux": "#00a0e2" };

const passengerAirlinesNormalized = new Set(passengerAirlines.map(normalizeAirlineName));
const cargoAirlinesNormalized = new Set(cargoAirlines.map(normalizeAirlineName));

const cargoPositionCodes = new Set([
    '601', '602', '603', '604', '605', '606',
    '601A', '602A', '603A', '604A', '605A',
    '601B', '602B', '603B', '604B'
]);

const semicontactoPositionCodes = new Set([
    '501', '502', '503', '504', '505'
]);

const remotePositionCodes = new Set([
    '506', '507', '508', '509', '510', '511', '512', '513', '514',
    '506A', '507A', '508A', '506B', '507B'
]);

const cobusAttentionPositions = new Set([
    '115', '115A', '115B', '116', '116A', '116B',
    '509', '510', '511', '512', '513', '514'
]);

const positionCategoryLabels = {
    cargo: 'Carga',
    semicontacto: 'Semicontacto',
    remote: 'Remota',
    terminal: 'Edificio terminal'
};

function normalizePositionValue(value) {
    return (value || '').toString().trim().toUpperCase();
}

function classifyPositionStand(value) {
    const normalized = normalizePositionValue(value);
    if (!normalized) return 'terminal';
    if (cargoPositionCodes.has(normalized)) return 'cargo';
    if (semicontactoPositionCodes.has(normalized)) return 'semicontacto';
    if (remotePositionCodes.has(normalized)) return 'remote';
    return 'terminal';
}

