const _CONCI_EXPORT_COLS_CARGA = [
    { h: 'DATOS SUBSECRETARIA', t: 'text', a: ['DATOS SUBSECRETARIA', 'CIERRE SUBSECRETARIA'] },
    { h: 'FECHA', t: 'date', a: ['FECHA'] },
    { h: 'TIPO DE MANIFIESTO', t: 'text', a: ['TIPO DE MANIFIESTO'] },
    { h: 'TIPO DE OPERACIÓN', t: 'optype', a: [] },
    { h: 'AEROLINEA', t: 'airline', a: ['AEROLINEA', 'AEROLÍNEA'] },
    { h: 'AERONAVE', t: 'aircraft', a: ['AERONAVE'] },
    { h: 'MATRÍCULA', t: 'text', a: ['MATRÍCULA', 'MATRICULA'] },
    { h: '# DE VUELO', t: 'text', a: ['# DE VUELO'] },
    { h: 'ORIGEN', t: 'codecity', a: ['ORIGEN'] },
    { h: 'ESCALA', t: 'codecity', a: ['ESCALA'] },
    { h: 'DESTINO', t: 'codecity', a: ['DESTINO'] },
    { h: 'SLOT ASIGNADO', t: 'datetime', a: ['SLOT ASIGNADO'] },
    { h: 'SLOT COORDINADO', t: 'datetime', a: ['SLOT COORDINADO'] },
    { h: 'HR. DE INICIO O TERMINO DE PERNOCTA', t: 'datetime', a: ['HR. DE INICIO O TERMINO DE PERNOCTA'] },
    { h: 'HR. DE EMBARQUE O DESEMBARQUE', t: 'datetime', a: ['HR. DE EMBARQUE O DESEMBARQUE'] },
    { h: 'HR. DE OPERACIÓN', t: 'datetime', a: ['HR. DE OPERACIÓN'] },
    { h: 'HR MÁXIMA DE ENTREGA', t: 'hrmax', a: [] },
    { h: 'HR. DE RECEPCIÓN', t: 'datetime', a: ['HR. DE RECEPCIÓN'] },
    { h: 'HR. CUMPLIDAS', t: 'hrscump', a: [] },
    { h: 'PUNTUALIDAD', t: 'puntualidad', a: [] },
    { h: 'IMPORTACIÓN', t: 'num', a: ['IMPORTACIÓN', 'IMPORTACION'] },
    { h: 'KGS CARGA LLEGADA NLU', t: 'num', a: ['KGS CARGA LLEGADA NLU', 'KGS. CARGA LLEGADA', 'KGS LLEGADA'] },
    { h: 'EXPORTACIÓN', t: 'num', a: ['EXPORTACIÓN', 'EXPORTACION'] },
    { h: 'KG. DE CARGA SALIDA NLU', t: 'num', a: ['KG. DE CARGA SALIDA NLU', 'KGS CARGA SALIDA NLU', 'KGS SALIDA'] },
    { h: 'TRANSITO', t: 'num', a: ['TRANSITO', 'TRANSITOS'] },
    { h: 'CORREO', t: 'num', a: ['CORREO'] },
    { h: 'DEMORA +-15 MIN', t: 'text', a: ['DEMORA +-15 MIN', 'DEMORA +- 15 MIN.', 'DEMORA +- 15 MIN'] },
    { h: 'MOTIVO', t: 'textwrap', a: ['MOTIVO', 'OBSERVACIONES'] },
    { h: 'CODIGO', t: 'text', a: ['CODIGO', 'CÓDIGO DEMORA'] },
    { h: 'CAPTURÓ', t: 'text', a: ['CAPTURÓ', 'CAPTURO'] },
];

// Localiza el valor de una fila probando alias exactos y luego una comparación
// normalizada (sin acentos/espacios/signos) contra las llaves reales.
function _conciExportGetField(row, aliases) {
    if (!row || !aliases) return '';
    for (const a of aliases) {
        const v = row[a];
        if (v !== undefined && v !== null && String(v).trim() !== '') return v;
    }
    const norm = (s) => String(s || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Z0-9]/g, '');
    const keys = Object.keys(row);
    for (const a of aliases) {
        const na = norm(a);
        for (const k of keys) {
            if (norm(k) === na) {
                const v = row[k];
                if (v !== undefined && v !== null && String(v).trim() !== '') return v;
            }
        }
    }
    return '';
}

// Convierte un color #RRGGBB a ARGB (FFRRGGBB) para ExcelJS.
function _conciHexToArgb(hex) {
    const h = String(hex || '').replace('#', '').trim();
    if (h.length === 6) return ('FF' + h).toUpperCase();
    if (h.length === 8) return h.toUpperCase();
    return 'FF000000';
}

// Valor real de una celda de la tabla, con la MISMA regla que usa el
// autoguardado (ver _conciAutoSaveRow): si hay un editor abierto manda lo que
// el usuario está escribiendo; en la columna de routing, dataset.raw guarda el
// nombre de ciudad ya resuelto para mostrar ("QUITO") y el valor real vive en
// dataset.routeRaw ("MEX-UIO"). Exportar con el mismo criterio con el que se
// guarda es lo que hace que el Excel coincida con la base.
function _conciExportCellRaw(td) {
    const col = td.dataset.col;
    const liveInput = td.querySelector('input, textarea, select');
    const fallbackRaw = _conciIsRoutingColumn(col)
        ? (td.dataset.routeRaw ?? td.dataset.raw ?? td.textContent)
        : (td.dataset.raw ?? td.textContent);
    return liveInput ? liveInput.value : (td.dataset.pendingRaw ?? fallbackRaw);
}

// Filas a exportar, tomadas de lo que está vivo en pantalla.
//
// Antes esto salía de _conciRenderCache. Esa caché se limpia en cada guardado
// exitoso — con razón, para que la vista nunca muestre datos viejos — y nada
// la vuelve a llenar hasta recargar la tabla, así que exportar justo después
// de capturar respondía "No hay datos cargados para exportar". Y mientras la
// caché sí existía, era una foto anterior: podía exportar sin lo recién
// capturado. Las dos caras del mismo problema desaparecen leyendo la tabla.
//
// Se exporta el día completo, no solo lo filtrado: las filas ocultas por un
// filtro siguen en el DOM (se ocultan con display:none) y aquí se incluyen a
// propósito, para no cambiar el alcance del reporte con este arreglo.
function _conciGetExportRows() {
    const rows = (_conciManifestosAllData || []).map((row, index) => {
        const overrides = _conciSummaryLiveOverrides.get(String(index));
        return overrides ? { ...row, ...overrides } : row;
    });
    const tbody = document.querySelector('#table-conci-manifiestos tbody');
    if (!tbody) return rows;

    // Lo capturado en esta sesión sobre filas ya cargadas, aunque el guardado
    // todavía no lo haya confirmado.
    tbody.querySelectorAll('tr[data-row-index]').forEach(tr => {
        const index = Number(tr.dataset.rowIndex);
        if (!Number.isInteger(index) || !rows[index]) return;
        const patch = {};
        tr.querySelectorAll('td[data-col]').forEach(td => {
            patch[td.dataset.col] = _conciExportCellRaw(td);
        });
        rows[index] = { ...rows[index], ...patch };
    });

    // Filas creadas en esta sesión: no existen en el conjunto cargado, así que
    // se agregan. Su data-row-index es "new" (no numérico), por lo que el
    // recorrido anterior no las tocó y no se duplican.
    tbody.querySelectorAll('tr[data-conci-new="1"], tr[data-conci-summary-persisted="1"]').forEach(tr => {
        const row = {};
        tr.querySelectorAll('td[data-col]').forEach(td => {
            row[td.dataset.col] = _conciExportCellRaw(td);
        });
        row._fuente = tr.dataset.rowFuente || '';
        rows.push(row);
    });

    return rows;
}

async function _conciExportToExcel(kind) {
    if (typeof ExcelJS === 'undefined' || typeof saveAs === 'undefined') {
        alert('No se pudo cargar la librería de Excel. Verifica tu conexión e inténtalo de nuevo.');
        return;
    }
    const rows = _conciGetExportRows();
    if (!rows.length) {
        alert('No hay datos cargados para exportar.');
        return;
    }
    const columns = _conciManifestosSummaryColumns;
    const year = _conciEditFallbackYear;
    const cols = (Array.isArray(columns) && columns.length) ? columns : Object.keys(rows[0] || {});
    const optypeCol  = cols.find(c => /tipo.*oper|service\s*type/i.test(c)) || null;
    const airlineCol = cols.find(c => /aerol[ií]nea|airline/i.test(c)) || null;

    const isCarga = kind === 'carga';
    const defs = isCarga ? _CONCI_EXPORT_COLS_CARGA : _CONCI_EXPORT_COLS_PAX;
    const dataRows = rows.filter(r => _conciRowIsCargo(r, optypeCol, airlineCol) === isCarga);
    if (!dataRows.length) {
        // Decía "en la vista actual", lo que daba a entender que respeta los
        // filtros de la tabla. No los respeta: exporta el día completo.
        alert(`No hay vuelos de ${isCarga ? 'carga' : 'pasajeros'} en el día cargado.`);
        return;
    }

    const get = _conciExportGetField;
    const routeCity = (raw, isArr) => {
        const parts = String(raw || '').toUpperCase().split(/[-\/]+/).filter(Boolean);
        const code = parts.length >= 2 ? (isArr ? parts[0] : parts[parts.length - 1]) : (parts[0] || '');
        if (!code) return String(raw || '');
        return window._iataToCity ? window._iataToCity(code) : code;
    };
    const codeCity = (raw) => {
        const s = String(raw || '').trim();
        if (!s) return '';
        if (/^[A-Za-z]{3}$/.test(s)) return window._iataToCity ? window._iataToCity(s.toUpperCase()) : s;
        return s;
    };
    const firstCode = (raw) => (String(raw || '').toUpperCase().split(/[-\/\s]+/).filter(Boolean)[0] || '');

    // Calcula el valor y estilo de una celda destino según su tipo.
    const computeCell = (def, row, isArr) => {
        const rawVal = def.a.length ? get(row, def.a) : '';
        switch (def.t) {
            case 'mes': {
                const n = parseInt(String(rawVal).trim(), 10);
                const v = (Number.isFinite(n) && n >= 1 && n <= 12) ? capitalizeFirst(SPANISH_MONTH_NAMES[n - 1]) : String(rawVal || '');
                return { value: v };
            }
            case 'date':
            case 'datetime':
                return { value: _conciFormatDisplayValue(def.h, rawVal, row, 'FECHA', year) };
            case 'airline': {
                const meta = _conciResolveAirlineMeta(rawVal);
                if (meta) {
                    return {
                        value: String(meta.name || rawVal || '').toUpperCase(),
                        fill: { type: 'pattern', pattern: 'solid', fgColor: { argb: _conciHexToArgb(meta.color || '#6c757d') } },
                        fontColor: _conciHexToArgb(meta.textColor || '#ffffff'),
                        bold: true,
                    };
                }
                return { value: String(rawVal || '') };
            }
            case 'aircraft': {
                const code = String(rawVal || '').trim().toUpperCase();
                const name = code ? _conciAircraftTypeByCode.get(code) : '';
                return { value: name || String(rawVal || '') };
            }
            case 'optype': {
                let code = '';
                if (isCarga) {
                    const o = get(row, ['ORIGEN']);
                    const d = get(row, ['DESTINO']);
                    code = firstCode(isArr ? (o || d) : (d || o));
                } else {
                    const routing = get(row, ['DESTINO / ORIGEN']);
                    const parts = String(routing || '').toUpperCase().split(/[-\/]+/).filter(Boolean);
                    code = parts.length >= 2 ? (isArr ? parts[0] : parts[parts.length - 1]) : (parts[0] || '');
                }
                return { value: code ? _conciOperacionNacInt(code) : '' };
            }
            case 'routecity':
                return { value: routeCity(rawVal, isArr) };
            case 'codecity':
                return { value: codeCity(rawVal) };
            case 'hrmax':
                return { value: _conciHrMaximaEntrega(get(row, ['HR. DE OPERACIÓN']), row, 'FECHA', year) };
            case 'hrscump': {
                const v = _conciHrsCumplidas(get(row, ['HR. DE OPERACIÓN']), get(row, ['HR. DE RECEPCIÓN']), year);
                const num = parseFloat(v);
                const out = { value: v, align: { vertical: 'middle', horizontal: 'center' } };
                if (Number.isFinite(num)) {
                    if (num < 30) { out.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE8F5E9' } }; out.fontColor = 'FF2E7D32'; out.bold = true; }
                    else if (num > 30) { out.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFEBEE' } }; out.fontColor = 'FFC62828'; out.bold = true; }
                }
                return out;
            }
            case 'puntualidad': {
                const estado = _conciPuntualidad(get(row, ['SLOT ASIGNADO']), get(row, ['HR. DE OPERACIÓN']), year);
                const styleMap = {
                    'EN TIEMPO':  { bg: 'FFE8F5E9', fg: 'FF2E7D32' },
                    'ANTES':      { bg: 'FFE8F5E9', fg: 'FF2E7D32' },
                    'ANTICIPADO': { bg: 'FFE3F2FD', fg: 'FF1565C0' },
                    'DESPUÉS':    { bg: 'FFFFF8E1', fg: 'FFEF6C00' },
                    'DEMORA':     { bg: 'FFFFEBEE', fg: 'FFC62828' },
                };
                const st = styleMap[estado];
                const out = { value: estado || '-' };
                if (st) { out.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: st.bg } }; out.fontColor = st.fg; out.bold = true; }
                return out;
            }
            case 'num': {
                const s = String(rawVal).trim();
                if (s === '') return { value: '', align: { vertical: 'middle', horizontal: 'right' } };
                const n = parseFloat(s.replace(/,/g, ''));
                return Number.isFinite(n)
                    ? { value: n, align: { vertical: 'middle', horizontal: 'right' } }
                    : { value: s, align: { vertical: 'middle', horizontal: 'right' } };
            }
            case 'textwrap':
                return { value: String(rawVal || ''), align: { vertical: 'middle', horizontal: 'left', wrapText: true } };
            default:
                return { value: String(rawVal || '') };
        }
    };

    const wb = new ExcelJS.Workbook();
    const ws = wb.addWorksheet(isCarga ? 'Carga' : 'Pasajeros', {
        views: [{ state: 'frozen', ySplit: 1 }],
    });
    const headers = defs.map(d => d.h.trim());
    ws.columns = headers.map(h => ({ header: h, key: h }));
    const maxLen = headers.map(h => h.length);
    const thin = { style: 'thin', color: { argb: 'FFBFBFBF' } };
    const border = { top: thin, left: thin, bottom: thin, right: thin };
    const baseFont = { name: 'Noto Sans', size: 10 };

    // Header
    const headerRow = ws.getRow(1);
    headerRow.height = 34;
    headerRow.eachCell((cell) => {
        cell.font = { name: 'Noto Sans', size: 10, bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF15683F' } };
        cell.alignment = { vertical: 'middle', horizontal: 'center', wrapText: true };
        cell.border = border;
    });

    // Data
    dataRows.forEach((row) => {
        const tipoRaw = String(get(row, ['TIPO DE MANIFIESTO']) || '').toLowerCase();
        const isArr = /lleg|arr/.test(tipoRaw);
        const cells = defs.map(d => computeCell(d, row, isArr));
        const xr = ws.addRow(cells.map(c => (c.value === undefined || c.value === null) ? '' : c.value));
        xr.eachCell((cell, colNumber) => {
            const meta = cells[colNumber - 1] || {};
            cell.font = { ...baseFont };
            if (meta.bold) cell.font.bold = true;
            if (meta.fontColor) cell.font.color = { argb: meta.fontColor };
            cell.alignment = meta.align || { vertical: 'middle', horizontal: 'center' };
            cell.border = border;
            if (meta.fill) cell.fill = meta.fill;
            const len = String(cell.value ?? '').length;
            if (len > maxLen[colNumber - 1]) maxLen[colNumber - 1] = len;
        });
    });

    ws.columns.forEach((col, i) => { col.width = Math.min(46, Math.max(11, maxLen[i] + 2)); });
    ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: headers.length } };

    const buf = await wb.xlsx.writeBuffer();
    const stamp = new Date().toISOString().slice(0, 10);
    const fname = `Conciliacion_${isCarga ? 'Carga' : 'Pasajeros'}_${stamp}.xlsx`;
    saveAs(new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), fname);
}
window.conciExportExcel = _conciExportToExcel;
// ─── Importación de archivos para Conciliación Manifiestos ───────────────────
// Cada manifiesto se identifica por Fecha + Tipo de manifiesto + Número de vuelo.
// Esa llave permite sustituir una carga previa sin añadir filas duplicadas.
const _CONCI_IMPORT_TABLE = 'Conciliación Manifiestos';
const _CONCI_IMPORT_FALLBACK_COLUMNS = [
    'CIERRE SUBSECRETARIA', 'MES', 'FECHA', 'TIPO DE MANIFIESTO', 'AEROLINEA',
    'TIPO DE OPERACIÓN', 'AERONAVE', 'MATRÍCULA', 'ESTATUS MATRÍCULA', '# DE VUELO',
    'DESTINO / ORIGEN', 'RUTA', 'SLOT ASIGNADO', 'SLOT COORDINADO',
    'HR. DE INICIO O TERMINO DE PERNOCTA', 'HR. DE EMBARQUE O DESEMBARQUE',
    'HR. DE OPERACIÓN', 'HR. MÁXIMA DE ENTREGA', 'HR. DE RECEPCIÓN',
    'HRS. CUMPLIDAS', 'PUNTUALIDAD / CANCELACIÓN', 'TOTAL PAX', 'DIPLOMATICOS',
    'EN COMISION', 'INFANTES', 'TRANSITOS', 'CONEXIONES', 'OTROS EXENTOS',
    'TOTAL EXENTOS', 'PAX QUE PAGAN TUA', 'KGS. DE EQUIPAJE',
    'KGS. DE CARGA NACIONAL', 'KGS. DE CARGA INTERNACIONAL', 'KG DE CARGA TOTAL',
    'CORREO', 'DEMORA +- 15 MIN.', 'CÓDIGO DEMORA', 'OBSERVACIONES', 'CAPTURÓ'
];
const _CONCI_IMPORT_IGNORED_COLUMNS = new Set([
    'id', 'created_at', 'updated_at', '_fuente', '_ispax', '_validadoitinerario',
    '_validadoporitinerario', '_concivueloid', '_concivuelodireccion', 'movement_key'
]);
const _CONCI_IMPORT_HEADER_ALIASES = {
    datos_subsecretaria: 'cierre_subsecretaria',
    hrs_cumplidas: 'hrs_cumplidas',
    hr_cumplidas: 'hrs_cumplidas',
    puntualidad: 'puntualidad_cancelacion',
    motivo: 'observaciones',
    codigo: 'codigo_demora',
    transito: 'transitos',
    demora_15_min: 'demora_15_min',
    demora_15_min_: 'demora_15_min'
};

function _conciImportNormalizeHeader(value) {
    return String(value == null ? '' : value)
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toLowerCase().replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
}

function _conciImportValue(value) {
    if (value === null || value === undefined) return '';
    if (value instanceof Date && !Number.isNaN(value.getTime())) {
        return `${String(value.getDate()).padStart(2, '0')}/${String(value.getMonth() + 1).padStart(2, '0')}/${value.getFullYear()}`;
    }
    return String(value).replace(/\u00a0/g, ' ').trim();
}

function _conciImportParseDelimitedLine(line, delimiter) {
    const out = [];
    let current = '';
    let quoted = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (ch === '"') {
            if (quoted && line[i + 1] === '"') {
                current += '"';
                i++;
            } else {
                quoted = !quoted;
            }
        } else if (ch === delimiter && !quoted) {
            out.push(current);
            current = '';
        } else {
            current += ch;
        }
    }
    out.push(current);
    return out;
}

function _conciImportDetectDelimiter(headerLine) {
    const candidates = [',', ';', '\t'];
    return candidates.reduce((best, delimiter) => {
        const count = _conciImportParseDelimitedLine(headerLine, delimiter).length;
        return count > best.count ? { delimiter, count } : best;
    }, { delimiter: ',', count: 1 }).delimiter;
}

async function _conciReadImportRows(file) {
    const name = String(file?.name || 'archivo').trim();
    if (!file) throw new Error('Selecciona un archivo para importar.');

    if (/\.csv$/i.test(name) || /text\/csv/i.test(String(file.type || ''))) {
        const text = (await file.text()).replace(/^\uFEFF/, '');
        const lines = text.split(/\r?\n/).filter(line => String(line).trim() !== '');
        if (lines.length < 2) throw new Error('El CSV no contiene encabezados y registros.');
        const delimiter = _conciImportDetectDelimiter(lines[0]);
        return {
            sheetName: 'CSV',
            headers: _conciImportParseDelimitedLine(lines[0], delimiter),
            rows: lines.slice(1).map(line => _conciImportParseDelimitedLine(line, delimiter))
        };
    }

    if (!/\.(xlsx|xls)$/i.test(name)) {
        throw new Error('Formato no compatible. Selecciona un archivo .xlsx, .xls o .csv.');
    }
    if (!window.XLSX) throw new Error('La librería de Excel aún no está disponible. Recarga la página e inténtalo de nuevo.');

    const workbook = XLSX.read(await file.arrayBuffer(), { type: 'array', cellDates: false });
    let fallback = null;
    for (const sheetName of workbook.SheetNames || []) {
        const sheet = workbook.Sheets[sheetName];
        if (!sheet) continue;
        const matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '', raw: false });
        const nonEmptyRows = matrix.filter(row => Array.isArray(row) && row.some(value => _conciImportValue(value) !== ''));
        if (nonEmptyRows.length < 2) continue;
        const headers = nonEmptyRows[0];
        const headerKeys = headers.map(_conciImportNormalizeHeader);
        const appearsToBeManifest = headerKeys.some(key => key === 'fecha')
            && headerKeys.some(key => key.includes('vuelo') || key.includes('flight'));
        const candidate = { sheetName, headers, rows: nonEmptyRows.slice(1) };
        if (appearsToBeManifest) return candidate;
        if (!fallback) fallback = candidate;
    }
    if (!fallback) throw new Error('No se encontró una hoja con encabezados y registros.');
    return fallback;
}

function _conciImportBuildColumnMap(headers, schemaColumns) {
    const destinationByKey = new Map();
    (schemaColumns || []).forEach(column => {
        const key = _conciImportNormalizeHeader(column);
        if (key && !_CONCI_IMPORT_IGNORED_COLUMNS.has(key)) destinationByKey.set(key, column);
    });

    return (headers || []).map((header, index) => {
        const sourceKey = _conciImportNormalizeHeader(header);
        const aliasKey = _CONCI_IMPORT_HEADER_ALIASES[sourceKey] || sourceKey;
        return { index, source: String(header || '').trim(), target: destinationByKey.get(aliasKey) || null };
    }).filter(item => item.target);
}

function _conciImportFindColumn(columns, kind) {
    const items = Array.isArray(columns) ? columns : [];
    if (kind === 'fecha') return items.find(column => /(^|_)fecha($|_)/.test(_conciImportNormalizeHeader(column))) || null;
    if (kind === 'tipo') return items.find(column => /tipo.*manifiest/.test(_conciImportNormalizeHeader(column))) || null;
    if (kind === 'vuelo') return items.find(column => /(?:^|_)(?:de_)?vuelo$|flight.*(?:number|designator)?/.test(_conciImportNormalizeHeader(column))) || null;
    if (kind === 'aerolinea') return items.find(column => /aerolinea|airline.*code|carrier/.test(_conciImportNormalizeHeader(column))) || null;
    if (kind === 'ruta') return items.find(column => /destino.*origen|origen.*destino|routing|route/.test(_conciImportNormalizeHeader(column))) || null;
    return null;
}

function _conciImportNormalizeManifestType(value) {
    const key = _conciImportNormalizeHeader(value);
    if (/lleg|arriv|arrival/.test(key)) return 'Llegada';
    if (/sal|dep|departure/.test(key)) return 'Salida';
    return '';
}

function _conciImportSignature(row, columns, fallbackYear) {
    const fecha = _conciImportValue(row?.[columns.fecha]);
    const tipo = _conciImportNormalizeManifestType(row?.[columns.tipo]);
    const normalizePart = value => _conciImportValue(value)
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toUpperCase().replace(/[^A-Z0-9]+/g, '');
    const aerolinea = normalizePart(row?.[columns.aerolinea]);
    let vuelo = normalizePart(row?.[columns.vuelo]);
    if (aerolinea && vuelo.startsWith(aerolinea)) vuelo = vuelo.slice(aerolinea.length);
    const numberMatch = vuelo.match(/(\d+[A-Z]?)$/);
    if (numberMatch) vuelo = numberMatch[1];
    const ruta = normalizePart(row?.[columns.ruta]);
    const parts = _conciParseDateTimeParts(fecha, fallbackYear);
    if (!parts || !Number.isFinite(parts.year) || !Number.isFinite(parts.month) || !Number.isFinite(parts.day)
        || !tipo || !aerolinea || !vuelo || !ruta) return null;
    if (parts.month < 1 || parts.month > 12 || parts.day < 1 || parts.day > 31) return null;
    const dateKey = `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`;
    const direction = tipo === 'Llegada' ? 'A' : 'D';
    return `${aerolinea}|${vuelo}|${dateKey}|${direction}|${ruta}`;
}

// Reescribe TOTAL EXENTOS y PAX QUE PAGAN TUA de un payload con la misma regla
// que usa la captura (ver _conciRefreshCalculatedCellsForRow). Solo toca la fila
// si trae algun rubro de pasajeros: una fila de carga no se altera.
function _conciTuaRecalcularPayload(payload) {
    if (!payload) return payload;
    const campos = _conciTuaCampos(Object.keys(payload));
    const traeRubros = campos.exentos.length > 0 || campos.totalPax;
    if (!traeRubros) return payload;
    const esperado = _conciTuaValoresEsperados(payload, campos);
    if (campos.totalExentos) payload[campos.totalExentos] = esperado.totalExentos;
    if (campos.paxTua) payload[campos.paxTua] = esperado.paxTua;
    return payload;
}

function _conciImportBuildRows(rawRows, columnMap, identityColumns, fallbackYear) {
    const uniqueRows = [];
    const invalidRows = [];
    const signatures = new Set();
    let repeatedInFile = 0;

    (rawRows || []).forEach((raw, rowIndex) => {
        const payload = {};
        columnMap.forEach(({ index, target }) => {
            const value = _conciImportValue(raw?.[index]);
            if (value !== '') payload[target] = _conciPrepareValueForDatabase(target, value);
        });
        if (!Object.keys(payload).length) return;

        const manifestType = _conciImportNormalizeManifestType(payload[identityColumns.tipo]);
        if (manifestType) payload[identityColumns.tipo] = manifestType;
        // El archivo puede traer TOTAL EXENTOS o PAX QUE PAGAN TUA descuadrados
        // respecto de sus propios rubros. Capturando celda por celda eso no puede
        // pasar (son columnas calculadas y bloqueadas), asi que se aplica aqui la
        // misma regla y la importacion guarda datos coherentes desde el principio.
        _conciTuaRecalcularPayload(payload);
        const signature = _conciImportSignature(payload, identityColumns, fallbackYear);
        if (!signature) {
            invalidRows.push(rowIndex + 2);
            return;
        }
        if (signatures.has(signature)) {
            repeatedInFile++;
            return;
        }
        signatures.add(signature);
        uniqueRows.push({ payload, signature, sourceRow: rowIndex + 2 });
    });

    return { uniqueRows, invalidRows, repeatedInFile };
}

async function _conciImportWriteRecords(client, records, existingBySignature) {
    const updates = [];
    const inserts = [];
    const extraIds = [];

    records.forEach(record => {
        const matches = existingBySignature.get(record.signature) || [];
        if (matches.length) {
            const primary = matches[0];
            if (primary.id === undefined || primary.id === null) {
                throw new Error('No se pudo identificar un registro existente para sustituirlo.');
            }
            updates.push({ record, id: primary.id });
            matches.slice(1).forEach(match => {
                if (match?.id !== undefined && match?.id !== null) extraIds.push(match.id);
            });
        } else {
            inserts.push({ record });
        }
    });

    const writeBatch = async (items, isUpdate) => {
        for (let i = 0; i < items.length; i += 20) {
            const batch = items.slice(i, i + 20);
            const results = await Promise.all(batch.map(async item => {
                const result = await _conciWriteRowSafe(client, item.record.payload, isUpdate ? item.id : null);
                if (!result.ok) throw new Error(result.error?.message || 'No se pudo guardar un registro del archivo.');
                return result;
            }));
            if (results.length !== batch.length) throw new Error('No se completó la escritura del archivo.');
        }
    };

    // Primero se actualiza/inserta; los duplicados viejos sólo se borran cuando
    // toda la nueva carga ya quedó guardada correctamente.
    await writeBatch(updates, true);
    await writeBatch(inserts, false);

    const idsToDelete = [...new Set(extraIds.map(String))];
    for (let i = 0; i < idsToDelete.length; i += 200) {
        const { error } = await client.from(_CONCI_IMPORT_TABLE).delete().in('id', idsToDelete.slice(i, i + 200));
        if (error) throw new Error(`Se importaron los registros, pero no se pudieron limpiar duplicados previos: ${error.message}`);
    }

    return { updated: updates.length, inserted: inserts.length, removed: idsToDelete.length };
}

async function _conciImportManifiestosFile(file) {
    if (!_conciCanCurrentUserManage()) {
        alert('Solo usuarios editor o admin pueden importar manifiestos.');
        return;
    }

    const button = document.getElementById('btn-conci-import-file');
    const defaultHtml = button?.innerHTML || '';
    if (button) {
        button.disabled = true;
        button.innerHTML = '<i class="fas fa-spinner fa-spin me-1"></i>Validando';
    }

    try {
        const parsed = await _conciReadImportRows(file);
        let client = window.supabaseClient;
        if (!client && window.ensureSupabaseClient) client = await window.ensureSupabaseClient();
        if (!client) throw new Error('No se pudo inicializar el cliente de Supabase.');

        const columnInfo = await _conciGetManifestColInfo(client);
        const schemaColumns = columnInfo?.sampleRow
            ? Object.keys(columnInfo.sampleRow)
            : _CONCI_IMPORT_FALLBACK_COLUMNS;
        const columnMap = _conciImportBuildColumnMap(parsed.headers, schemaColumns);
        if (!columnMap.length) throw new Error('Los encabezados del archivo no coinciden con los campos de Conciliación Manifiestos.');

        const identityColumns = {
            fecha: _conciImportFindColumn(schemaColumns, 'fecha'),
            tipo: _conciImportFindColumn(schemaColumns, 'tipo'),
            vuelo: _conciImportFindColumn(schemaColumns, 'vuelo'),
            aerolinea: _conciImportFindColumn(schemaColumns, 'aerolinea'),
            ruta: _conciImportFindColumn(schemaColumns, 'ruta')
        };
        if (!identityColumns.fecha || !identityColumns.tipo || !identityColumns.vuelo
            || !identityColumns.aerolinea || !identityColumns.ruta) {
            throw new Error('No se pudo identificar la llave compuesta (AEROLINEA, # DE VUELO, FECHA, TIPO DE MANIFIESTO y DESTINO / ORIGEN).');
        }

        const identitySelect = ['id', ...Object.values(identityColumns)]
            .map(column => column === 'id' ? column : `"${String(column).replace(/"/g, '""')}"`)
            .join(',');
        const existingResult = await _concifetchAllRows(client, _CONCI_IMPORT_TABLE, {
            select: identitySelect,
            batchSize: 5000,
            orderBy: [{ column: 'id', ascending: true }]
        });
        if (existingResult.error) throw new Error(`No se pudieron verificar duplicados: ${existingResult.error.message}`);
        const existingRows = existingResult.data || [];

        const fallbackYear = Number(document.getElementById('filter-conci-manifiestos-year')?.value) || new Date().getFullYear();
        const prepared = _conciImportBuildRows(parsed.rows, columnMap, identityColumns, fallbackYear);
        if (prepared.invalidRows.length) {
            const sample = prepared.invalidRows.slice(0, 8).join(', ');
            const extra = prepared.invalidRows.length > 8 ? '…' : '';
            throw new Error(`Las filas ${sample}${extra} no tienen una llave completa: AEROLINEA, # DE VUELO, FECHA, TIPO DE MANIFIESTO y DESTINO / ORIGEN. Corrige el archivo para poder evitar duplicados.`);
        }
        if (!prepared.uniqueRows.length) throw new Error('No se encontraron registros válidos para importar.');

        const existingBySignature = new Map();
        existingRows.forEach(row => {
            const signature = _conciImportSignature(row, identityColumns, fallbackYear);
            if (!signature) return;
            if (!existingBySignature.has(signature)) existingBySignature.set(signature, []);
            existingBySignature.get(signature).push(row);
        });

        const matched = prepared.uniqueRows.filter(record => existingBySignature.has(record.signature));
        const existingMatches = matched.reduce((sum, record) => sum + (existingBySignature.get(record.signature)?.length || 0), 0);
        const newCount = prepared.uniqueRows.length - matched.length;
        const repeatedNote = prepared.repeatedInFile
            ? `\nAdemás, se descartarán ${prepared.repeatedInFile} repetido(s) dentro del mismo archivo.`
            : '';
        const message = matched.length
            ? `Se detectaron ${matched.length} manifiesto(s) ya cargado(s) (${existingMatches} fila(s) existente(s)).\n\nSe sustituirán por los datos del archivo y se eliminarán las coincidencias duplicadas.\nTambién se agregarán ${newCount} manifiesto(s) nuevo(s).${repeatedNote}\n\n¿Deseas continuar?`
            : `Se importarán ${newCount} manifiesto(s) nuevo(s) desde “${file.name}”.${repeatedNote}\n\n¿Deseas continuar?`;
        if (!confirm(message)) return;

        if (button) button.innerHTML = '<i class="fas fa-spinner fa-spin me-1"></i>Importando';
        const outcome = await _conciImportWriteRecords(client, prepared.uniqueRows, existingBySignature);
        _conciRawCache = null;
        _conciRenderCache.clear();
        _conciRenderedKey = '';
        _conciManifestColInfo = null;
        await loadConciliacionManifiestos({ forceRefresh: true });
        alert(`Importación terminada: ${outcome.inserted} nuevo(s), ${outcome.updated} sustituido(s)${outcome.removed ? ` y ${outcome.removed} duplicado(s) anterior(es) eliminado(s)` : ''}.`);
    } catch (error) {
        console.error('[Conciliación] error al importar manifiestos:', error);
        alert(`No se importó el archivo: ${error.message || error}`);
    } finally {
        if (button) {
            button.innerHTML = defaultHtml;
            _conciRefreshEditToolbar();
        }
    }
}

function _conciSummaryColumnKey(value) {
    return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toUpperCase()
        .replace(/[^A-Z0-9]+/g, '');
}

function _conciSummaryNumber(value) {
    if (value === null || value === undefined || value === '') return 0;
    const raw = String(value).trim().replace(/\s/g, '').replace(/,/g, '');
    const number = Number(raw.replace(/[^0-9.-]/g, ''));
    return Number.isFinite(number) ? number : 0;
}

function _conciSummaryFindColumn(columns, predicate) {
    return (columns || []).find(column => predicate(_conciSummaryColumnKey(column))) || null;
}

// Una celda "capturada" es la que trae algo escrito, aunque sea un 0. Sirve
// para distinguir "se capturaron 0 kg" de "nadie ha capturado kilos todavía":
// son cosas muy distintas para quien arma el reporte del día.
function _conciSummaryHasValue(value) {
    return value !== null && value !== undefined && String(value).trim() !== '';
}

// Localiza las columnas de kilogramos de carga de la tabla.
//
// Antes esto era una sola búsqueda "la primera columna que hable de KG y de
// CARGA", y como el orden de columnas es NACIONAL → INTERNACIONAL → TOTAL,
// siempre ganaba la nacional: la tarjeta ignoraba la carga internacional y el
// total. En un aeropuerto donde la mayor parte de la carga es internacional,
// eso se veía en pantalla como decenas de operaciones de carga y "N/D" en
// kilogramos.
//
// KGS. DE EQUIPAJE queda fuera a propósito: es equipaje de pasajeros, no carga.
function _conciSummaryCargoColumns(columns) {
    const cols = columns || [];
    const total = _conciSummaryFindColumn(cols, key => key.includes('CARGATOTAL'));
    const nacional = _conciSummaryFindColumn(cols, key => key.includes('CARGANACIONAL'));
    const internacional = _conciSummaryFindColumn(cols, key => key.includes('CARGAINTERNACIONAL'));
    // Respaldo para conjuntos de datos que no traigan ninguna de las tres
    // (por ejemplo un Excel externo con otro encabezado).
    const generico = (total || nacional || internacional)
        ? null
        : _conciSummaryFindColumn(cols, key =>
            key.includes('CARGA')
            && !key.includes('EQUIPAJE')
            && (key.includes('KG') || key.includes('KILO') || key.includes('PESO'))
        );
    return { total, nacional, internacional, generico };
}

// Kilogramos de carga de UNA fila. Si viene capturado el total, ese manda; si
// no, se suman nacional e internacional. Nunca los tres a la vez: el total ya
// incluye a los otros dos y se contarían doble.
//
// Devuelve también si la fila tenía algo capturado, para que el llamador pueda
// mostrar 0 cuando se capturó cero y "N/D" cuando nadie capturó nada.
function _conciSummaryCargoKgs(row, cargoCols) {
    if (!row || !cargoCols) return { kgs: 0, captured: false };
    const { total, nacional, internacional, generico } = cargoCols;

    if (total && _conciSummaryHasValue(row[total])) {
        return { kgs: _conciSummaryNumber(row[total]), captured: true };
    }
    const tieneNacional = nacional && _conciSummaryHasValue(row[nacional]);
    const tieneInternacional = internacional && _conciSummaryHasValue(row[internacional]);
    if (tieneNacional || tieneInternacional) {
        return {
            kgs: (tieneNacional ? _conciSummaryNumber(row[nacional]) : 0)
                + (tieneInternacional ? _conciSummaryNumber(row[internacional]) : 0),
            captured: true,
        };
    }
    if (generico && _conciSummaryHasValue(row[generico])) {
        return { kgs: _conciSummaryNumber(row[generico]), captured: true };
    }
    return { kgs: 0, captured: false };
}

function _conciReadLiveTableRow(tr) {
    const row = {};
    tr.querySelectorAll('td[data-col]').forEach(td => {
        const input = td.querySelector('input, textarea, select');
        row[td.dataset.col] = input
            ? input.value
            : (td.dataset.pendingRaw !== undefined ? td.dataset.pendingRaw : (td.dataset.raw || td.textContent || ''));
    });
    row._fuente = tr.dataset.rowFuente || '';
    return row;
}

function _conciGetLiveSummaryRows() {
    const rows = (_conciManifestosAllData || []).map((row, index) => {
        const overrides = _conciSummaryLiveOverrides.get(String(index));
        return overrides ? { ...row, ...overrides } : row;
    });
    const tbody = document.querySelector('#table-conci-manifiestos tbody');
    if (tbody) {
        tbody.querySelectorAll('tr[data-conci-new="1"], tr[data-conci-summary-persisted="1"]').forEach(tr => {
            rows.push(_conciReadLiveTableRow(tr));
        });
    }
    return rows;
}

function _conciRefreshSummaryCardsLive() {
    const rows = _conciGetLiveSummaryRows();
    _conciUpdateResumen(rows, _conciManifestosSummaryColumns);
    _updateManifiestosSummaryStrip(rows, _conciManifestosSummaryColumns);
}

function _conciUpdateSummaryLiveCell(td, value) {
    const tr = td?.closest('tr');
    if (!tr) return;
    const rowIndex = tr.dataset.rowIndex;
    if (rowIndex !== undefined && rowIndex !== '' && !String(rowIndex).startsWith('new')) {
        const overrides = _conciSummaryLiveOverrides.get(String(rowIndex)) || {};
        overrides[td.dataset.col] = value;
        _conciSummaryLiveOverrides.set(String(rowIndex), overrides);
    }
    _conciRefreshSummaryCardsLive();
}

// Recalcula de forma independiente pasajeros y carga: una fila puede contener
// PAX y también kilogramos de carga/equipaje.
function _updateManifiestosSummaryStrip(data, columns) {
    const strip = document.getElementById('manifiestos-summary-strip');
    if (!strip) return;
    const rows = Array.isArray(data) ? data : [];
    const cols = columns || (rows.length ? Object.keys(rows[0]) : []);
    if (!rows.length) { strip.classList.add('d-none'); return; }

    const airlineCol = _conciSummaryFindColumn(cols, key => key.includes('AEROLINEA') || key.includes('AIRLINE'));
    const optypeCol = _conciSummaryFindColumn(cols, key =>
        (key.includes('TIPO') && key.includes('OPER')) || key.includes('SERVICETYPE')
    );
    const totalPaxCol = _conciSummaryFindColumn(cols, key => key === 'TOTALPAX' || key.includes('TOTALPAX'));
    const cargoCols = _conciSummaryCargoColumns(cols);

    let paxOps = 0, totalPax = 0, cargoOps = 0, kgsCarga = 0;
    let kgsCapturados = false;
    for (const row of rows) {
        const isCargoByType = _conciRowIsCargo(row, optypeCol, airlineCol);
        const paxValue = totalPaxCol ? _conciSummaryNumber(row[totalPaxCol]) : 0;
        const kgs = _conciSummaryCargoKgs(row, cargoCols);

        if (isCargoByType) {
            cargoOps++;
        } else {
            paxOps++;
            totalPax += paxValue;
        }
        // Los KGS son una métrica independiente; no cambian la categoría ni
        // el número de operaciones.
        kgsCarga += kgs.kgs;
        if (kgs.captured) kgsCapturados = true;
    }

    const fmt = n => n.toLocaleString('es-MX');
    const setEl = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    setEl('mf-sum-pax-ops', fmt(paxOps));
    setEl('mf-sum-total-pax', fmt(totalPax));
    setEl('mf-sum-cargo-ops', fmt(cargoOps));
    // "N/D" solo cuando de verdad nadie capturó kilos. Si se capturaron y suman
    // cero, se muestra 0: es un dato, no una ausencia de dato.
    setEl('mf-sum-kgs-carga', kgsCapturados ? fmt(Math.round(kgsCarga)) : 'N/D');
    strip.classList.remove('d-none');
}

// Ajusta el alto del contenedor con scroll (#conci-manifiestos-scroll) al
// espacio real disponible entre su borde superior y el final de la
// ventana, en vez de un alto fijo en px — así se aprovecha toda la pantalla
// y la tabla queda "fija" en ese rango: solo su contenido interno se
// desplaza (vertical y horizontal), nunca la página completa.
let _conciScrollResizeTimer = null;
// ── Columnas fijas al desplazar horizontalmente ──────────────────────────────
//
// Ninguna columna queda fija horizontalmente: encabezado, filtro y datos deben
// desplazarse juntos para evitar que FECHA, AEROLÍNEA o # DE VUELO se empalmen
// sobre las columnas que el usuario está consultando.
const _CONCI_COLUMNAS_FIJAS = [];

function _conciEsColumnaFija(columna) {
    const key = _conciNormalizedColumnName(columna);
    return _CONCI_COLUMNAS_FIJAS.some(patron => patron.test(key));
}

// Los desplazamientos se calculan del ancho real de cada columna, no de un
// valor fijo: las columnas se pueden redimensionar y ocultar. Una columna
// oculta mide 0 y por eso desaparece sola del calculo.
function _conciSyncColumnasFijas() {
    const tabla = document.getElementById('table-conci-manifiestos');
    if (!tabla || tabla.offsetParent === null) return;
    const thead = tabla.querySelector('thead');
    if (!thead) return;

    const encabezados = [...thead.querySelectorAll('tr:first-child th[data-conci-column-key]')];
    let acumulado = 0;
    const offsets = new Map();
    encabezados.forEach(th => {
        const columna = th.dataset.conciColumnKey;
        if (!_conciEsColumnaFija(columna)) return;
        offsets.set(columna, acumulado);
        acumulado += th.getBoundingClientRect().width;
    });

    const ultima = [...offsets.keys()].pop() || null;
    tabla.querySelectorAll('[data-conci-column-key]').forEach(celda => {
        const columna = celda.dataset.conciColumnKey;
        // Los filtros deben desplazarse junto con su columna. Si también se
        // vuelven sticky, los tres inputs de FECHA/AEROLÍNEA/# DE VUELO quedan
        // flotando sobre los filtros visibles al mover la tabla a la derecha.
        const esFiltro = !!celda.closest('tr.conci-filter-row');
        if (!offsets.has(columna) || esFiltro) {
            celda.classList.remove('conci-col-fija', 'conci-col-fija-ultima');
            celda.style.removeProperty('left');
            return;
        }
        celda.classList.add('conci-col-fija');
        celda.classList.toggle('conci-col-fija-ultima', columna === ultima);
        celda.style.left = `${Math.round(offsets.get(columna))}px`;
    });
}

function _conciSyncScrollHeight() {
    const wrap = document.getElementById('conci-manifiestos-scroll');
    if (!wrap || wrap.offsetParent === null) return; // pestaña oculta: nada que medir
    if (document.body.classList.contains('conci-manifest-workspace')) {
        wrap.style.maxHeight = '';
        return;
    }
    const top = wrap.getBoundingClientRect().top;
    const available = window.innerHeight - top - 16;
    wrap.style.maxHeight = `${Math.max(available, 240)}px`;
}

// La vista de Manifiestos funciona como una hoja de cálculo de altura completa.
// Sólo cambia el layout: los nodos, controles y listeners existentes se conservan.
function _conciUpdateWorkspaceMode() {
    const section = document.getElementById('conciliacion-section');
    const manifestPane = document.getElementById('pane-conci-comercial');
    const itineraryPane = document.getElementById('pane-conci-itinerario');
    const enabled = !!(section?.classList.contains('active') &&
        (manifestPane?.classList.contains('active') || itineraryPane?.classList.contains('active')));
    document.body.classList.toggle('conci-manifest-workspace', enabled);
    document.body.classList.toggle('conci-itinerary-workspace',
        !!(enabled && itineraryPane?.classList.contains('active')));
    requestAnimationFrame(_conciSyncScrollHeight);
}

window.conciReturnToMainMenu = function () {
    document.body.classList.remove('conci-manifest-workspace', 'conci-itinerary-workspace');
    if (typeof window._navdeckShowMenu === 'function') {
        window._navdeckShowMenu();
    }
};

document.addEventListener('DOMContentLoaded', () => {
    ['tab-conci-comercial', 'tab-conci-itinerario'].forEach(id => {
        document.getElementById(id)?.addEventListener('shown.bs.tab', _conciUpdateWorkspaceMode);
    });
    document.querySelectorAll('.menu-item[data-section]').forEach(link => {
        link.addEventListener('click', () => setTimeout(_conciUpdateWorkspaceMode, 0));
    });
    _conciUpdateWorkspaceMode();
});

// Ctrl+B / Ctrl+F abre el buscador rápido de la pestaña activa de Conciliación.
// Fuera de estas dos vistas no se intercepta el comportamiento del navegador.
document.addEventListener('keydown', event => {
    if (!(event.ctrlKey || event.metaKey) || event.altKey || event.shiftKey) return;
    const key = String(event.key || '').toLowerCase();
    if (key !== 'b' && key !== 'f') return;
    const section = document.getElementById('conciliacion-section');
    if (!section?.classList.contains('active')) return;

    const manifestActive = document.getElementById('pane-conci-comercial')?.classList.contains('active');
    const itineraryActive = document.getElementById('pane-conci-itinerario')?.classList.contains('active');
    const input = manifestActive
        ? document.getElementById('conci-quick-flight')
        : itineraryActive ? document.getElementById('itin-quick-flight') : null;
    if (!input) return;

    event.preventDefault();
    event.stopPropagation();
    input.focus();
    input.select();
}, true);

// Ctrl+G guarda de inmediato todo lo capturado en Conciliación Manifiestos, sin
// tener que soltar el teclado para ir al botón — quien captura trabaja con las
// dos manos en las teclas y bajar al ratón por cada confirmación cuesta.
//
// Va en fase de captura y con preventDefault porque Ctrl+G es "buscar siguiente"
// en el navegador; sólo se intercepta dentro de esta pestaña, en cualquier otra
// parte de la aplicación el atajo del navegador sigue intacto. Se acepta también
// mientras el foco está dentro de un editor de celda: ahí es justo donde estará
// el foco al terminar de capturar, y el propio guardado cierra ese editor
// aceptando lo que se acaba de escribir.
document.addEventListener('keydown', event => {
    if (!(event.ctrlKey || event.metaKey) || event.altKey || event.shiftKey) return;
    if (String(event.key || '').toLowerCase() !== 'g') return;
    const section = document.getElementById('conciliacion-section');
    if (!section?.classList.contains('active')) return;
    if (!document.getElementById('pane-conci-comercial')?.classList.contains('active')) return;
    if (!document.getElementById('table-conci-manifiestos')) return;

    event.preventDefault();
    event.stopPropagation();
    _conciGuardarTodoAhora();
}, true);
window.addEventListener('resize', () => {
    clearTimeout(_conciScrollResizeTimer);
    _conciScrollResizeTimer = setTimeout(() => {
        _conciSyncScrollHeight();
        _conciSyncColumnasFijas();
    }, 120);
});

function _renderConciManifiestosTable(data, columns, fallbackYear) {
    const tableId = 'table-conci-manifiestos';

    _conciManifestosAllData = Array.isArray(data) ? data : [];
    _conciManifestosSummaryColumns = Array.isArray(columns) ? columns : [];
    _conciSummaryLiveOverrides.clear();

    _conciUpdateResumen(data, columns);
    _conciBindCountPills();
    _updateManifiestosSummaryStrip(data, columns);
    // Restaura la visibilidad del desglose y el resaltado según el filtro activo.
    const _paxDet = document.getElementById('conci-count-pax-detail');
    if (_paxDet) _paxDet.classList.toggle('d-none', _conciClassFilter !== 'pax');
    const _cargaDet = document.getElementById('conci-count-carga-detail');
    if (_cargaDet) _cargaDet.classList.toggle('d-none', _conciClassFilter !== 'carga');
    _conciUpdatePillActiveStyles();

    if (_conciManifiestosDataTable) {
        try { _conciManifiestosDataTable.destroy(); } catch(_) {}
        _conciManifiestosDataTable = null;
    }

    const table = document.getElementById(tableId);
    if (!table) return;

    const thead = table.querySelector('thead');
    const tbody = table.querySelector('tbody');
    _conciBindRowActions();
    thead.innerHTML = '';
    tbody.innerHTML = '';
    _conciManifestosAllData = data; // Guarda referencia para las listas de valores de filtros desplegables

    // Display columns: hide the internal marker columns
    const displayCols = (columns || (data.length ? Object.keys(data[0]) : [])).filter(c => !['_fuente', '_isPax', '_validado_itinerario', '_validado_por_itinerario', 'id', 'Año', 'Mes', 'Día'].includes(c));
    const showRowActions = _conciCanCurrentUserEdit();
    _conciRenderColumnVisibilityMenu(displayCols);

    // Detect semantic columns for smart city-name display in routing/origen cell
    const _tipoCol    = displayCols.find(c => /tipo.*(manif)/i.test(c)) || null;
    const _airlineCol = displayCols.find(c => /aerol[ií]nea|airline/i.test(c)) || null;
    const _matriculaStatusCol = displayCols.find(c => /estatus.*matr[ií]cula|status.*matr[ií]cula/i.test(c)) || null;
    // Columna "AERONAVE": muestra el nombre del modelo (catálogo aircraft type.csv) en vez del código IATA/ICAO crudo.
    const _aeronaveCol = displayCols.find(c => /^aeronave$/i.test(c.trim())) || null;
    // Match columns named exactly 'Routing' OR containing 'origen' or 'destino' (e.g. 'DESTINO / ORIGEN')
    const _routingCol = displayCols.find(c => /^routing$/i.test(c) || /origen|destino.*origen|routing/i.test(c)) || null;
    // Columna "RUTA": muestra la pierna completa (origen-destino) sin maquillar.
    const _rutaCol = displayCols.find(c => /^ruta$/i.test(c.trim())) || null;
    // Columna "TIPO DE OPERACIÓN": se muestra como Nacional / Internacional según el
    // origen/destino del vuelo (no como el service type F/J/P original).
    const _optypeCol  = displayCols.find(c => /tipo.*oper|service\s*type/i.test(c)) || null;
    // Columnas para calcular HRS. CUMPLIDAS = (HR. DE RECEPCIÓN − HR. DE OPERACIÓN) × 24.
    const _hrsCumplidasCol = displayCols.find(c => /hrs?\.?\s*cumplidas/i.test(c)) || null;
    const _hrOperacionCol  = displayCols.find(c => /hr\.?\s*de\s*oper/i.test(c)) || null;
    const _hrRecepcionCol  = displayCols.find(c => /hr\.?\s*de\s*recep/i.test(c)) || null;
    const _slotAsignadoCol = displayCols.find(c => /slot\s*asignad/i.test(c)) || null;
    const _slotCoordinadoCol = displayCols.find(c => /slot\s*coordinad/i.test(c)) || null;
    const _puntualidadCol  = displayCols.find(c => /puntualidad|cancelaci/i.test(c)) || null;
    const _demora15Col = displayCols.find(c => /demora\s*\+\s*-?\s*15\s*min/i.test(c)) || null;
    const _hrMaxEntregaCol = displayCols.find(c => /hr\.?\s*m[aá]xima\s*de\s*entrega/i.test(c)) || null;
    // Columna "FACTOR DE OCUPACIÓN": pax/capacidad — se resalta en rojo cuando hay sobrecupo.
    const _factorOcupacionCol = displayCols.find(c => /factor.*ocupaci[oó]n/i.test(c)) || null;
    // Columna "CAPTURÓ": se muestra como avatar con iniciales (nombre completo al pasar el ratón).
    const _capturoCol = displayCols.find(c => /^captur[oó]$/i.test(c.trim())) || null;
    // Columna "MES": muestra el nombre del mes en español en vez del número (1-12).
    const _mesCol = displayCols.find(c => /^mes$/i.test(c)) || null;
    const _fechaCol   = displayCols.find(c => /(^|\b)fecha(\b|$)/i.test(c)) || null;
    _conciEditFallbackYear = fallbackYear;
    _conciEditFechaCol     = _fechaCol;

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="100%" class="text-center text-muted py-5">No se encontraron registros para los filtros seleccionados.</td></tr>';
        _conciRefreshEditToolbar();
        return;
    }

    // Header — sticky (CSS-based, no DataTables split-table misalignment)
    const trHead = document.createElement('tr');
    displayCols.forEach(c => {
        const th = document.createElement('th');
        th.className = 'text-nowrap conci-th';
        th.dataset.conciColumnKey = c;
        const thInner = document.createElement('div');
        thInner.className = 'conci-th-inner';
        const thLabel = document.createElement('span');
        thLabel.textContent = c;
        const thBtn = document.createElement('button');
        thBtn.type = 'button';
        thBtn.className = 'conci-ef-btn';
        thBtn.title = 'Filtrar por ' + c;
        thBtn.dataset.col = c;
        thBtn.innerHTML = '<i class="fas fa-filter" aria-hidden="true"></i>';
        thInner.appendChild(thLabel);
        thInner.appendChild(thBtn);
        th.appendChild(thInner);
        trHead.appendChild(th);
    });
    // Columna “Itinerario”: indica si el vuelo fue validado en la pestaña de Itinerario de Vuelos
    const itTh = document.createElement('th');
    itTh.className = 'text-nowrap conci-th conci-it-val-col';
    itTh.title = 'Validación del vuelo en el Itinerario de Vuelos';
    itTh.innerHTML = '<i class="fas fa-check-circle me-1"></i>Itinerario';
    trHead.appendChild(itTh);
    if (showRowActions) {
        const actionTh = document.createElement('th');
        actionTh.className = 'text-nowrap conci-th conci-row-action-col';
        actionTh.textContent = 'Acciones';
        actionTh.dataset.conciAction = '1';
        trHead.appendChild(actionTh);
    }
    thead.appendChild(trHead);

    // Vincular botones de filtro Excel (delegación, se asocia una vez por ciclo de render).
    if (!thead.dataset.conciEfBound) {
        thead.dataset.conciEfBound = '1';
        thead.addEventListener('click', (ev) => {
            const btn = ev.target.closest('.conci-ef-btn');
            if (!btn) return;
            ev.stopPropagation();
            const col = btn.dataset.col;
            if (col) _showConciExcelFilter(col, btn);
        });
    }
    _updateConciExcelFilterIcons();

    // ── Fila de filtros de columna ────────────────────────────────────────────
    const trFilter = document.createElement('tr');
    trFilter.className = 'conci-filter-row';
    displayCols.forEach(c => {
        const thF = document.createElement('th');
        thF.className = 'conci-th-filter';
        thF.dataset.conciColumnKey = c;
        const inp = document.createElement('input');
        inp.type = 'text';
        inp.className = 'form-control form-control-sm conci-col-filter';
        inp.placeholder = 'Filtrar…';
        inp.dataset.col = c;
        inp.value = _conciColFilters[c] || '';
        inp.setAttribute('aria-label', 'Filtrar ' + c);
        thF.appendChild(inp);
        trFilter.appendChild(thF);
    });
    const thFIt = document.createElement('th');
    thFIt.className = 'conci-th-filter';
    trFilter.appendChild(thFIt);
    if (showRowActions) {
        const thFAct = document.createElement('th');
        thFAct.className = 'conci-th-filter';
        trFilter.appendChild(thFAct);
    }
    thead.appendChild(trFilter);
    _conciApplyColumnVisibility();

    // Delegar eventos de escritura en la fila de filtros (bind único por render).
    if (!thead.dataset.conciColFilterBound) {
        thead.dataset.conciColFilterBound = '1';
        thead.addEventListener('input', (ev) => {
            const inp2 = ev.target.closest('.conci-col-filter');
            if (!inp2) return;
            const col = inp2.dataset.col;
            if (col !== undefined) {
                const v = inp2.value;
                if (v && v.trim()) { _conciColFilters[col] = v; }
                else { delete _conciColFilters[col]; }
            }
            clearTimeout(_conciColFilterDebounce);
            _conciColFilterDebounce = setTimeout(_conciApplyPillFilter, 200);
        });
    }

    // Navegación con flechas desde la fila de filtros: ↓ entra a la tabla
    // (misma columna, primera fila visible editable) y ←/→ pasan al filtro
    // de la columna vecina — solo cuando el cursor ya está en el extremo del
    // texto, para no robarle la flecha a la edición normal del filtro.
    if (!thead.dataset.conciColFilterKeyBound) {
        thead.dataset.conciColFilterKeyBound = '1';
        thead.addEventListener('keydown', (ev) => {
            const inp = ev.target.closest('.conci-col-filter');
            if (!inp) return;
            if (ev.key === 'ArrowDown') {
                ev.preventDefault();
                const col = inp.dataset.col;
                for (const tr of _conciVisibleBodyRows()) {
                    const cell = _conciGetCellInRow(tr, col);
                    if (cell) {
                        _conciAsegurarCeldaVisible(cell, 'vertical');
                        _conciActivateCellEditor(cell);
                        break;
                    }
                }
            } else if (ev.key === 'ArrowRight' || ev.key === 'ArrowLeft') {
                const atStart = inp.selectionStart === 0 && inp.selectionEnd === 0;
                const atEnd = inp.selectionStart === inp.value.length && inp.selectionEnd === inp.value.length;
                const inputs = _conciGetVisibleFilterInputs();
                const idx = inputs.indexOf(inp);
                if (ev.key === 'ArrowRight' && atEnd && idx >= 0 && idx < inputs.length - 1) {
                    ev.preventDefault();
                    inputs[idx + 1].focus();
                    inputs[idx + 1].select();
                } else if (ev.key === 'ArrowLeft' && atStart && idx > 0) {
                    ev.preventDefault();
                    inputs[idx - 1].focus();
                    inputs[idx - 1].select();
                }
            }
        });
    }

    // Ajustar top de la fila de filtros al alto real del encabezado (sticky),
    // y el alto del contenedor con scroll para aprovechar la pantalla.
    requestAnimationFrame(() => {
        const headerRow = thead.querySelector('tr:first-child');
        if (headerRow && table) {
            table.style.setProperty('--conci-head-h', Math.ceil(headerRow.getBoundingClientRect().height) + 'px');
        }
        _conciSyncScrollHeight();
        _conciSyncColumnasFijas();
        // Repone las capturas que quedaron pendientes de guardar y las reintenta.
        _conciRestaurarBorradores();
        // Y lo que quedo pendiente en OTRAS computadoras, que aqui no se
        // reintenta solo y hay que poder rescatar a mano.
        _conciCargarPendientesRemotos();
        _conciRepintarEstelas();
        _conciRepintarConflictos();
        _conciMarcarFilasSinCaptura();
        _conciMarcarFilasIncompletas();
    });

    // Encabezado fijo vía CSS (position:sticky). Sin manipulación de transform
    // por JS para evitar el parpadeo al hacer scroll.

    const rowToneCount = 2;

    if (tbody.dataset.conciRowSelectBound !== 'true') {
        tbody.dataset.conciRowSelectBound = 'true';
        tbody.addEventListener('click', (event) => {
            const interactiveTarget = event.target.closest('button, a, input, textarea, select, label');
            if (interactiveTarget) return;
            const tr = event.target.closest('tr');
            if (!tr || !tbody.contains(tr)) return;

            tbody.querySelectorAll('tr.conci-row-selected').forEach((row) => {
                row.classList.remove('conci-row-selected');
                row.setAttribute('aria-selected', 'false');
            });

            tr.classList.add('conci-row-selected');
            tr.setAttribute('aria-selected', 'true');
        });
    }

    // Body (lazy append: keeps DOM smaller, improving horizontal scroll smoothness)
    const renderSeq = ++_conciRenderSeq;
    const batchSize = 250;
    let idx = 0;
    let appendScheduled = false;
    const scrollWrap = table.closest('.table-responsive');

    // Per-render memoization caches: many cells share the same value/airline/airport,
    // so memoizing avoids recomputing identical work for thousands of rows.
    const _airlineMetaCache = new Map();
    const resolveAirlineMeta = (raw) => {
        if (_airlineMetaCache.has(raw)) return _airlineMetaCache.get(raw);
        const meta = _conciResolveAirlineMeta(raw);
        _airlineMetaCache.set(raw, meta);
        return meta;
    };
    const _iataCityCache = new Map();
    const iataToCity = (code) => {
        if (_iataCityCache.has(code)) return _iataCityCache.get(code);
        const city = window._iataToCity ? window._iataToCity(code) : code;
        _iataCityCache.set(code, city);
        return city;
    };
    const _displayValueCache = new Map();
    const formatDisplay = (col, val, row) => {
        const rawKey = (val === null || val === undefined) ? '' : String(val);
        // Skip cache if column requires per-row context (e.g. row-date for time-only cells)
        const useCache = !/(hora|hr\.?\s*de|slot|sibt|aibt|aldt|sobt|aobt|atot|attt)/i.test(col);
        const cacheKey = useCache ? `${col}\u0001${rawKey}` : null;
        if (cacheKey && _displayValueCache.has(cacheKey)) return _displayValueCache.get(cacheKey);
        const out = _conciFormatDisplayValue(col, val, row, _fechaCol, fallbackYear);
        if (cacheKey) _displayValueCache.set(cacheKey, out);
        return out;
    };

    // Precompute column metadata once instead of running regex tests per cell.
    const hasIataMap = !!window._iataToCity;
    const hasAirportCatalog = _conciAirportCatalogByIata.size > 0;
    const colMeta = displayCols.map(c => ({
        c,
        isAirline:   c === _airlineCol,
        isMatriculaStatus: c === _matriculaStatusCol,
        isAeronave:  c === _aeronaveCol,
        isRouting:   c === _routingCol && (hasIataMap || hasAirportCatalog),
        isRuta:      c === _rutaCol,
        isOptype:    c === _optypeCol,
        isHrsCumplidas: c === _hrsCumplidasCol && !!_hrOperacionCol && !!_hrRecepcionCol,
        isPuntualidad: c === _puntualidadCol && !!_slotAsignadoCol && !!_hrOperacionCol,
        isDemora15: c === _demora15Col && !!_hrOperacionCol,
        isHrMaxEntrega: c === _hrMaxEntregaCol && !!_hrOperacionCol,
        isMes: c === _mesCol,
        isEvidencia: /evidencia/i.test(c),
        isFactorOcupacion: c === _factorOcupacionCol,
        isCapturo: c === _capturoCol,
    }));

    // Extrae el código IATA del extremo relevante (origen si es llegada, destino si
    // es salida) a partir del valor de routing "AAA-BBB" o "AAA/BBB".
    const _routingEndpointCode = (routingRaw, tipoRaw) => {
        const isArr = /lleg|arr/i.test(String(tipoRaw || ''));
        const parts = String(routingRaw || '').toUpperCase().split(/[-\/]+/).filter(Boolean);
        if (parts.length >= 2) return isArr ? parts[0] : parts[parts.length - 1];
        return parts[0] || '';
    };
    const _optypeCache = new Map();
    const resolveOptype = (routingRaw, tipoRaw) => {
        const key = `${routingRaw}\u0001${tipoRaw}`;
        if (_optypeCache.has(key)) return _optypeCache.get(key);
        const code = _routingEndpointCode(routingRaw, tipoRaw);
        const out = _conciOperacionNacInt(code);
        _optypeCache.set(key, out);
        return out;
    };

    const appendBatch = () => {
        appendScheduled = false;
        if (renderSeq !== _conciRenderSeq) return;

        const frag = document.createDocumentFragment();
        const end = Math.min(idx + batchSize, data.length);

        for (; idx < end; idx++) {
            const row = data[idx];
            const tr = document.createElement('tr');
            const tone = idx % rowToneCount;
            tr.classList.add(`conci-row-tone-${tone}`);
            const _rowId = row.id !== undefined && row.id !== null ? String(row.id) : '';
            const _rowFuente = row['_fuente'] || '';
            tr.dataset.rowId = _rowId;
            tr.dataset.rowFuente = _rowFuente;
            tr.dataset.rowIndex = String(idx);
            if (row._conci_vuelo_id !== undefined && row._conci_vuelo_id !== null) {
                tr.dataset.conciVueloId = String(row._conci_vuelo_id);
                tr.dataset.conciVueloDireccion = String(row._conci_vuelo_direccion || '');
            }

            // Etiqueta la fila para los filtros por pill (clase pax/carga y dirección).
            const _tipoRaw = _tipoCol ? String(row[_tipoCol] || '').toLowerCase() : '';
            tr.dataset.rowDir = /lleg|arr/.test(_tipoRaw) ? 'arr' : (/sal|dep/.test(_tipoRaw) ? 'dep' : '');
            tr.dataset.rowCargo = _conciRowIsCargo(row, _optypeCol, _airlineCol) ? '1' : '0';
            const _isCargoRow = tr.dataset.rowCargo === '1';
            tr.dataset.rowOvercap = row._conci_overcapacity ? '1' : '0';
            if (row._conci_overcapacity) {
                tr.classList.add('conci-row-overcapacity');
                tr.title = `Sobrecupo: ${row._conci_overcapacity_diff} pasajero(s) por encima de la capacidad máxima de la aeronave.`;
            }

            displayCols.forEach((c, ci) => {
                const meta = colMeta[ci];
                const td = document.createElement('td');
                td.className = 'conci-cell';
                td.dataset.conciColumnKey = c;
                if (_conciHiddenColumns.has(c)) td.classList.add('d-none');
                td.dataset.col = c;
                // La celda imprime el valor tal cual viene de la base, donde el
                // tipo de manifiesto está en mayúsculas por la importación. Al
                // editar se guarda 'Llegada'/'Salida', así que sin esto una fila
                // ya editada quedaba en minúsculas junto a las demás.
                if (_conciIsManifestTypeColumn(c)) td.classList.add('conci-manifest-type-cell');
                if (_conciIsCalculatedColumn(c)) {
                    td.dataset.conciReadonly = '1';
                    td.title = 'Campo calculado: no se puede modificar.';
                } else if (_isCargoRow && _conciIsPassengerColumn(c)) {
                    td.dataset.conciReadonly = '1';
                    td.title = 'Vuelo de carga: no aplica la captura de pasajeros.';
                }
                const val = row[c];
                const rawStr = String(val !== null && val !== undefined ? val : '').trim();
                td.dataset.raw = rawStr;

                if (meta.isMatriculaStatus) {
                    const status = rawStr || 'NO IDENTIFICADA';
                    _conciRenderMatriculaStatusCell(td, status, !!row._conci_matricula_mismatch, row._conci_matricula_catalog_airline || '');
                    if (row._conci_matricula_mismatch) tr.classList.add('conci-matricula-mismatch');
                } else if (meta.isAirline) {
                    const airlineMeta = resolveAirlineMeta(rawStr);
                    if (airlineMeta) {
                        td.style.textAlign = 'center';
                        td.textContent = String(airlineMeta.name || rawStr).toUpperCase();
                        if (rawStr && rawStr.toUpperCase() !== String(airlineMeta.name || '').toUpperCase()) td.title = rawStr;
                    } else {
                        td.textContent = rawStr;
                    }
                    // El color lo aplica el mismo helper que usa el editor, para
                    // que abrir la celda no pueda repintarla de otro color.
                    _conciApplyAirlineCellPreview(td);
                } else if (meta.isAeronave) {
                    const code = rawStr.toUpperCase();
                    const name = code ? _conciAircraftTypeByCode.get(code) : '';
                    td.textContent = name || rawStr;
                    if (name && name.toUpperCase() !== rawStr.toUpperCase()) td.title = rawStr;
                } else if (meta.isRouting) {
                    const tipo = _tipoCol ? String(row[_tipoCol] || '') : '';
                    const isArr = /lleg|arr/i.test(tipo);
                    const parts = rawStr.toUpperCase().split(/[-\/]+/);
                    const code = (parts.length >= 2)
                        ? (isArr ? parts[0] : parts[parts.length - 1])
                        : (parts[0] || '');
                    const catalogCity = code ? _conciAirportStoredValue(_conciAirportCatalogByIata.get(code)) : '';
                    const city = _conciCiudadBonita(catalogCity || (code ? iataToCity(code) : rawStr));
                    const shown = city || rawStr;
                    td.textContent = shown;
                    td.dataset.routeRaw = rawStr;
                    td.dataset.raw = shown;
                    if (rawStr && rawStr.toUpperCase() !== String(shown).toUpperCase()) td.title = rawStr;
                } else if (meta.isRuta) {
                    // RUTA: pierna completa (origen-destino) tal cual; si la fila aun
                    // no tiene RUTA propia, cae al routing crudo de DESTINO / ORIGEN.
                    const routingRaw = _routingCol ? String(row[_routingCol] || '').trim() : '';
                    const shownRuta = (rawStr || routingRaw).toUpperCase();
                    td.textContent = shownRuta;
                    td.dataset.raw = shownRuta;
                } else if (meta.isOptype) {
                    const routingRaw = _routingCol ? String(row[_routingCol] || '') : '';
                    const tipoRaw = _tipoCol ? String(row[_tipoCol] || '') : '';
                    const storedOptype = String(row[c] || '').trim();
                    const op = _conciNormalizeOperationType(storedOptype) || resolveOptype(routingRaw, tipoRaw);
                    _conciRenderOperationTypeCell(td, op);
                } else if (meta.isHrsCumplidas) {
                    const opRaw = _hrOperacionCol ? row[_hrOperacionCol] : '';
                    const recRaw = _hrRecepcionCol ? row[_hrRecepcionCol] : '';
                    const hrs = _conciHrsCumplidas(opRaw, recRaw, fallbackYear);
                    _conciRenderHrsCumplidasCell(td, hrs);
                } else if (meta.isPuntualidad) {
                    const slotRaw = _slotAsignadoCol ? row[_slotAsignadoCol] : '';
                    const opRaw = _hrOperacionCol ? row[_hrOperacionCol] : '';
                    const estado = _conciPuntualidad(slotRaw, opRaw, fallbackYear);
                    td.dataset.raw = estado;
                    if (estado && estado !== '-') {
                        const styleMap = {
                            'EN TIEMPO':  { bg: '#e8f5e9', bd: '#8bc34a', fg: '#2e7d32', icon: 'fa-check' },
                            'ANTES':      { bg: '#e8f5e9', bd: '#8bc34a', fg: '#2e7d32', icon: 'fa-arrow-left' },
                            'ANTICIPADO': { bg: '#e3f2fd', bd: '#64b5f6', fg: '#1565c0', icon: 'fa-forward' },
                            'DESPUÉS':    { bg: '#fff8e1', bd: '#ffb300', fg: '#ef6c00', icon: 'fa-clock' },
                            'DEMORA':     { bg: '#ffebee', bd: '#e57373', fg: '#c62828', icon: 'fa-exclamation-triangle' },
                        };
                        const st = styleMap[estado] || { bg: '#eceff1', bd: '#b0bec5', fg: '#455a64', icon: 'fa-circle-info' };
                        const badge = document.createElement('span');
                        badge.style.cssText = `display:inline-block;padding:2px 10px;border-radius:999px;font-size:0.72rem;font-weight:700;line-height:1.2;border:1px solid ${st.bd};background:${st.bg};color:${st.fg};`;
                        badge.innerHTML = `<i class="fas ${st.icon} me-1"></i>${estado}`;
                        td.appendChild(badge);
                    } else {
                        td.textContent = '-';
                        td.dataset.raw = '-';
                    }
                } else if (meta.isDemora15) {
                    const demora = _conciDemoraMinutos(
                        _slotAsignadoCol ? row[_slotAsignadoCol] : '',
                        _slotCoordinadoCol ? row[_slotCoordinadoCol] : '',
                        _hrOperacionCol ? row[_hrOperacionCol] : '',
                        fallbackYear
                    );
                    _conciRenderDemoraMinutosCell(td, demora);
                } else if (meta.isHrMaxEntrega) {
                    const opRaw = _hrOperacionCol ? row[_hrOperacionCol] : '';
                    const maxEntrega = _conciHrMaximaEntrega(opRaw, row, _fechaCol, fallbackYear);
                    td.textContent = maxEntrega;
                    td.dataset.raw = maxEntrega;
                } else if (meta.isMes) {
                    const mesNum = parseInt(rawStr, 10);
                    const mesName = (Number.isFinite(mesNum) && mesNum >= 1 && mesNum <= 12)
                        ? capitalizeFirst(SPANISH_MONTH_NAMES[mesNum - 1])
                        : rawStr;
                    td.textContent = mesName;
                    td.dataset.raw = mesName;
                } else if (meta.isEvidencia) {
                    // Si es la columna de evidencia de PDF y trae link
                    if (rawStr && (rawStr.startsWith('http') || rawStr.endsWith('.pdf'))) {
                        const a = document.createElement('a');
                        a.href = rawStr;
                        a.target = '_blank'; // Abrir en nueva pestaña
                        a.rel = 'noopener noreferrer';
                        a.className = 'btn btn-sm btn-outline-danger py-0 px-2';
                        a.style.cssText = 'border-radius: 4px; font-weight: 500; font-size: 0.75rem; display: inline-flex; align-items: center; gap: 4px;';
                        a.innerHTML = '<i class="fas fa-file-pdf"></i> Ver PDF';
                        td.appendChild(a);
                    } else {
                        td.textContent = rawStr;
                    }
                } else if (meta.isFactorOcupacion) {
                    _conciRenderFactorOcupacionCell(td, rawStr, !!row._conci_overcapacity, row._conci_overcapacity_diff || 0);
                } else if (meta.isCapturo) {
                    _conciRenderCapturoCell(td, rawStr);
                } else {
                    const displayValue = formatDisplay(c, val, row);
                    td.textContent = displayValue;
                    if (displayValue && String(displayValue) !== rawStr) td.title = rawStr;
                }

                tr.appendChild(td);
            });

            // Recalcula las formulas tanto al cargar como durante la captura.
            _conciRefreshCalculatedCellsForRow(tr);
            _conciRenderDescuadreTua(tr, row);

            // ── Celda de validación Itinerario ─────────────────────────────────
            {
                const isValidadoIt = row['_validado_itinerario'] === true;
                const validadoPorIt = String(row['_validado_por_itinerario'] || '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
                const itTd = document.createElement('td');
                itTd.className = 'conci-cell conci-it-val-cell text-center';
                if (isValidadoIt) {
                    tr.dataset.rowValidadoIt = '1';
                    tr.classList.add('conci-validated-itinerario');
                    const badge = document.createElement('span');
                    badge.className = 'conci-it-valid-badge';
                    badge.title = validadoPorIt ? `Validado por: ${validadoPorIt}` : 'Validado en Itinerario';
                    badge.innerHTML = '<i class="fas fa-check-circle me-1"></i>Validado';
                    itTd.appendChild(badge);
                    if (_rowFuente === 'Solo Vuelos') tr.classList.add('conci-missing-manifiesto');
                } else {
                    itTd.innerHTML = '<span class="text-muted" style="font-size:.7rem">—</span>';
                }
                tr.appendChild(itTd);
            }
            if (showRowActions) {
                const actionTd = document.createElement('td');
                actionTd.className = 'conci-row-action-col text-center';
                actionTd.dataset.conciAction = '1';
                _conciFillRowActionCell(actionTd, String(row.id ?? '').trim());
                tr.appendChild(actionTd);
            }

            frag.appendChild(tr);
        }

        tbody.appendChild(frag);
        // Resalta en las filas recién insertadas las celdas que otros usuarios
        // conectados tengan abiertas ahora mismo (carga inicial y scroll perezoso).
        _conciApplyRemotePresenceHighlights();

        // Re-aplica todos los filtros activos (pill + columna) a las filas recién agregadas.
        if (_conciClassFilter || _conciDirFilter || _conciOvercapFilter || _conciCaptureFilter || Object.values(_conciColFilters).some(v => v && v.trim())) _conciApplyPillFilter();

        if (idx >= data.length) {
            if (scrollWrap && scrollWrap._conciLazyHandler) {
                scrollWrap.removeEventListener('scroll', scrollWrap._conciLazyHandler);
                delete scrollWrap._conciLazyHandler;
            }
            _conciRefreshEditToolbar();
            return;
        }

        // If viewport is still not full, keep appending in next frame.
        if (scrollWrap && scrollWrap.scrollHeight <= (scrollWrap.clientHeight + 80)) {
            scheduleAppend();
        }
    };

    const scheduleAppend = () => {
        if (appendScheduled || renderSeq !== _conciRenderSeq || idx >= data.length) return;
        appendScheduled = true;
        window.requestAnimationFrame(appendBatch);
    };

    const onLazyScroll = () => {
        if (renderSeq !== _conciRenderSeq || !scrollWrap) return;
        if (idx >= data.length) return;
        const nearBottom = (scrollWrap.scrollTop + scrollWrap.clientHeight) >= (scrollWrap.scrollHeight - 240);
        if (nearBottom) scheduleAppend();
    };

    if (scrollWrap) {
        if (scrollWrap._conciLazyHandler) {
            scrollWrap.removeEventListener('scroll', scrollWrap._conciLazyHandler);
        }
        scrollWrap._conciLazyHandler = onLazyScroll;
        scrollWrap.addEventListener('scroll', onLazyScroll, { passive: true });

        // Suaviza el scroll: mientras el usuario se desplaza, marca el contenedor
        // como "is-scrolling" para desactivar transiciones/hover (evita jank) y
        // lo quita ~140 ms después de que se detiene el desplazamiento.
        if (!scrollWrap._conciSmoothHandler) {
            const smoothHandler = () => {
                if (!scrollWrap.classList.contains('is-scrolling')) {
                    scrollWrap.classList.add('is-scrolling');
                }
                if (scrollWrap._conciScrollIdleTimer) {
                    clearTimeout(scrollWrap._conciScrollIdleTimer);
                }
                scrollWrap._conciScrollIdleTimer = setTimeout(() => {
                    scrollWrap.classList.remove('is-scrolling');
                }, 140);
            };
            scrollWrap._conciSmoothHandler = smoothHandler;
            scrollWrap.addEventListener('scroll', smoothHandler, { passive: true });
        }
    }

    _conciRefreshEditToolbar();
    scheduleAppend();

    // Auto-activar modo editar para usuarios con rol de edición
    // sin necesidad de hacer clic en el botón "Editar".
    if (_conciCanCurrentUserEdit() && !_conciEditMode) {
        _conciEnsureEditStyles();
        _conciEditMode = true;
        _conciSetTableEditableState(true);
        _conciRefreshEditToolbar();
    }
}

